CREATE OR REPLACE FUNCTION public.mt_check_rate_limit(identifier text, ceiling integer) RETURNS boolean
LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
DECLARE current_hits integer;
BEGIN
  IF identifier !~ '^[a-f0-9]{64}$' OR ceiling < 1 OR ceiling > 100 THEN RAISE EXCEPTION 'Invalid rate limit'; END IF;
  DELETE FROM public.mt_rate_limits WHERE expires_at < now();
  INSERT INTO public.mt_rate_limits(key,hits,expires_at) VALUES(identifier,1,now()+interval '15 minutes')
  ON CONFLICT(key) DO UPDATE SET hits = public.mt_rate_limits.hits + 1
  RETURNING hits INTO current_hits;
  RETURN current_hits <= ceiling;
END;
$$;
