CREATE POLICY mt_daily_picks_public ON public.mt_daily_picks FOR SELECT TO anon,authenticated USING (EXISTS(SELECT 1 FROM public.mt_places p WHERE p.id=place_id AND p.published AND p.access<>'restricted' AND p.community_count>=3));
CREATE OR REPLACE FUNCTION public.mt_refresh_daily_picks() RETURNS void
LANGUAGE plpgsql SECURITY INVOKER SET search_path='' AS $$
BEGIN
  PERFORM pg_advisory_xact_lock(29092026);
  DELETE FROM public.mt_daily_picks;
  INSERT INTO public.mt_daily_picks(place_id,position)
    SELECT id,row_number() OVER(ORDER BY community_rating DESC,community_count DESC,id)::smallint
    FROM public.mt_places WHERE published AND access<>'restricted' AND community_count>=3
    ORDER BY community_rating DESC,community_count DESC,id LIMIT 5;
END; $$;
REVOKE ALL ON FUNCTION public.mt_refresh_daily_picks() FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.mt_refresh_daily_picks() TO service_role;

-- Listing status and facts extracted from cited sources. Nothing is ever deleted: a place that is
-- no longer open to visitors is archived (hidden) with its reason and evidence, and can be restored.
ALTER TABLE public.mt_places ADD COLUMN IF NOT EXISTS details jsonb NOT NULL DEFAULT '{}'::jsonb;
ALTER TABLE public.mt_places ADD COLUMN IF NOT EXISTS listing_status text NOT NULL DEFAULT 'active';
ALTER TABLE public.mt_places ADD COLUMN IF NOT EXISTS archived boolean NOT NULL DEFAULT false;
ALTER TABLE public.mt_places ADD COLUMN IF NOT EXISTS status_checked_at timestamptz;

DO $constraints$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'mt_places_details_object') THEN
    ALTER TABLE public.mt_places ADD CONSTRAINT mt_places_details_object
      CHECK (jsonb_typeof(details) = 'object' AND pg_column_size(details) <= 16000);
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'mt_places_listing_status') THEN
    ALTER TABLE public.mt_places ADD CONSTRAINT mt_places_listing_status
      CHECK (listing_status IN ('active','needs_review','closed'));
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'mt_places_archived_hidden') THEN
    ALTER TABLE public.mt_places ADD CONSTRAINT mt_places_archived_hidden CHECK (NOT (archived AND published));
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'mt_places_closed_archived') THEN
    ALTER TABLE public.mt_places ADD CONSTRAINT mt_places_closed_archived CHECK (listing_status <> 'closed' OR archived);
  END IF;
END
$constraints$;

-- Every status change keeps its reason and evidence. Only administrators can read it.
CREATE TABLE IF NOT EXISTS public.mt_listing_audits (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  place_id bigint NOT NULL REFERENCES public.mt_places(id) ON DELETE CASCADE,
  from_status text NOT NULL CHECK (from_status IN ('active','needs_review','closed')),
  to_status text NOT NULL CHECK (to_status IN ('active','needs_review','closed')),
  reason text NOT NULL CHECK (char_length(reason) BETWEEN 1 AND 1000),
  evidence_url text CHECK (evidence_url IS NULL OR (evidence_url LIKE 'https://%' AND char_length(evidence_url) <= 2000)),
  checked_on date NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS mt_listing_audits_place ON public.mt_listing_audits(place_id, created_at DESC);
ALTER TABLE public.mt_listing_audits ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.mt_listing_audits FROM anon, authenticated;
GRANT SELECT ON public.mt_listing_audits TO authenticated;
GRANT ALL ON public.mt_listing_audits TO service_role;
GRANT USAGE, SELECT ON SEQUENCE public.mt_listing_audits_id_seq TO service_role;
DROP POLICY IF EXISTS mt_listing_audits_admin ON public.mt_listing_audits;
CREATE POLICY mt_listing_audits_admin ON public.mt_listing_audits FOR SELECT TO authenticated USING ((SELECT public.mt_is_admin()));

-- One transaction per change: status, visibility and the audit row cannot drift apart.
-- Closing archives and hides the place. Reopening restores only what this function hid, so an
-- editorial draft (unpublished, never archived) stays a draft.
CREATE OR REPLACE FUNCTION public.mt_set_listing_status(target_place bigint, new_status text, why text, evidence text, checked date) RETURNS void
LANGUAGE plpgsql SECURITY INVOKER SET search_path = '' AS $$
DECLARE previous text;
BEGIN
  IF new_status NOT IN ('active','needs_review','closed') THEN RAISE EXCEPTION 'Invalid listing status' USING ERRCODE = '22023'; END IF;
  SELECT listing_status INTO previous FROM public.mt_places WHERE id = target_place FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Place not found' USING ERRCODE = '23503'; END IF;
  IF new_status = 'closed' THEN
    UPDATE public.mt_places SET listing_status = 'closed', archived = true, published = false, status_checked_at = now() WHERE id = target_place;
  ELSE
    UPDATE public.mt_places SET listing_status = new_status, published = CASE WHEN archived THEN true ELSE published END, archived = false, status_checked_at = now() WHERE id = target_place;
  END IF;
  INSERT INTO public.mt_listing_audits(place_id, from_status, to_status, reason, evidence_url, checked_on)
    VALUES (target_place, previous, new_status, why, evidence, checked);
END;
$$;
REVOKE ALL ON FUNCTION public.mt_set_listing_status(bigint, text, text, text, date) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.mt_set_listing_status(bigint, text, text, text, date) TO service_role;

-- Photos attached to reviews. Reviews are public text, but their photos are for signed-in people only.
-- The rule is enforced in the database, not just hidden in the UI: guests have no grant on the table or
-- the function below, and the files sit in the private mt-submissions bucket, reachable only through
-- short-lived signed links that the API hands out to signed-in sessions.
CREATE TABLE IF NOT EXISTS public.mt_review_photos (
  id uuid PRIMARY KEY,
  review_id bigint NOT NULL REFERENCES public.mt_reviews(id) ON DELETE CASCADE,
  user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
  path text NOT NULL UNIQUE,
  created_at timestamptz NOT NULL DEFAULT now(),
  CHECK(path ~ '^[a-f0-9-]{36}/[a-f0-9-]{36}\.jpg$')
);
CREATE INDEX IF NOT EXISTS mt_review_photos_review_idx ON public.mt_review_photos(review_id);
CREATE INDEX IF NOT EXISTS mt_review_photos_user_idx ON public.mt_review_photos(user_id);

-- A photo belongs to its author's own review, and a review holds at most three. The review row is
-- locked first so two uploads at once cannot both slip past the limit.
CREATE OR REPLACE FUNCTION mt_private.check_review_photo() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
BEGIN
  PERFORM 1 FROM public.mt_reviews WHERE id=NEW.review_id AND user_id=NEW.user_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Photos can only be added to your own review' USING ERRCODE='42501'; END IF;
  IF (SELECT count(*) FROM public.mt_review_photos WHERE review_id=NEW.review_id) >= 3 THEN
    RAISE EXCEPTION 'A review can have up to 3 photos' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
END; $$;
REVOKE ALL ON FUNCTION mt_private.check_review_photo() FROM PUBLIC;
DROP TRIGGER IF EXISTS mt_review_photo_check ON public.mt_review_photos;
CREATE TRIGGER mt_review_photo_check BEFORE INSERT ON public.mt_review_photos FOR EACH ROW EXECUTE FUNCTION mt_private.check_review_photo();

-- Deleting a photo, its review or its author's account queues the file for removal from storage.
CREATE OR REPLACE FUNCTION mt_private.queue_review_photo_deletion() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
BEGIN
  INSERT INTO public.mt_photo_deletions(path) VALUES(OLD.path) ON CONFLICT DO NOTHING;
  RETURN NULL;
END; $$;
REVOKE ALL ON FUNCTION mt_private.queue_review_photo_deletion() FROM PUBLIC;
DROP TRIGGER IF EXISTS mt_review_photo_deleted ON public.mt_review_photos;
CREATE TRIGGER mt_review_photo_deleted AFTER DELETE ON public.mt_review_photos FOR EACH ROW EXECUTE FUNCTION mt_private.queue_review_photo_deletion();

ALTER TABLE public.mt_review_photos ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.mt_review_photos FROM anon, authenticated;
GRANT SELECT ON public.mt_review_photos TO authenticated;
GRANT ALL ON public.mt_review_photos TO service_role;
DROP POLICY IF EXISTS mt_review_photos_signed_in ON public.mt_review_photos;
CREATE POLICY mt_review_photos_signed_in ON public.mt_review_photos FOR SELECT TO authenticated USING(true);

-- The photos on the same page of reviews that mt_place_community returns. Signed-in callers only.
-- The public mt_place_community function is left as it was and never mentions photos.
CREATE OR REPLACE FUNCTION public.mt_place_review_photos(target_place bigint, page_offset integer DEFAULT 0) RETURNS jsonb
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = '' AS $$
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Sign in to see photos' USING ERRCODE='42501'; END IF;
  IF page_offset < 0 OR page_offset > 10000 THEN RAISE EXCEPTION 'Invalid page'; END IF;
  IF NOT EXISTS(SELECT 1 FROM public.mt_places WHERE id=target_place AND published) THEN RETURN '[]'::jsonb; END IF;
  RETURN coalesce((
    SELECT jsonb_agg(jsonb_build_object('id',ph.id,'reviewId',ph.review_id,'path',ph.path) ORDER BY ph.created_at,ph.id)
    FROM public.mt_review_photos ph
    WHERE ph.review_id IN (SELECT r.id FROM public.mt_reviews r WHERE r.place_id=target_place ORDER BY r.created_at DESC,r.id DESC LIMIT 20 OFFSET page_offset)
  ),'[]'::jsonb);
END; $$;
REVOKE ALL ON FUNCTION public.mt_place_review_photos(bigint,integer) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.mt_place_review_photos(bigint,integer) TO authenticated;

-- One-time recovery codes: a way to reset a forgotten password without sending any email.
-- Only hashes are stored. Neither guests nor signed-in browsers can touch the table or call the functions
-- below; only the server, using the service role, can. The readable codes exist once, when they are issued.
CREATE TABLE IF NOT EXISTS public.mt_recovery_codes (
  id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
  code_hash text NOT NULL,
  used_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS mt_recovery_codes_unused_idx ON public.mt_recovery_codes(user_id) WHERE used_at IS NULL;
ALTER TABLE public.mt_recovery_codes ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.mt_recovery_codes FROM anon, authenticated;
GRANT ALL ON public.mt_recovery_codes TO service_role;

-- Replaces every code of an account with a new set, in one step, so a failure never leaves it with none.
CREATE OR REPLACE FUNCTION public.mt_replace_recovery_codes(target uuid, hashes jsonb) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
BEGIN
  IF jsonb_typeof(hashes) <> 'array' OR jsonb_array_length(hashes) NOT BETWEEN 1 AND 16 THEN RAISE EXCEPTION 'Invalid recovery codes' USING ERRCODE='22023'; END IF;
  DELETE FROM public.mt_recovery_codes WHERE user_id=target;
  INSERT INTO public.mt_recovery_codes(user_id,code_hash) SELECT target, value FROM jsonb_array_elements_text(hashes);
END; $$;

-- The unused codes of the account that owns an email address, for the server to check a code against.
CREATE OR REPLACE FUNCTION public.mt_recovery_candidates(account_email text) RETURNS jsonb
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = '' AS $$
  SELECT coalesce(jsonb_agg(jsonb_build_object('userId',u.id,'codeId',c.id,'hash',c.code_hash)),'[]'::jsonb)
  FROM auth.users u JOIN public.mt_recovery_codes c ON c.user_id=u.id AND c.used_at IS NULL
  WHERE lower(u.email)=lower(account_email);
$$;

-- Uses a code up. True for exactly one caller, however many try at the same moment.
CREATE OR REPLACE FUNCTION public.mt_consume_recovery_code(code_id bigint) RETURNS boolean
LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
BEGIN
  UPDATE public.mt_recovery_codes SET used_at=now() WHERE id=code_id AND used_at IS NULL;
  RETURN FOUND;
END; $$;

CREATE OR REPLACE FUNCTION public.mt_recovery_codes_left(target uuid) RETURNS integer
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = '' AS $$
  SELECT count(*)::integer FROM public.mt_recovery_codes WHERE user_id=target AND used_at IS NULL;
$$;

-- Signs an account out everywhere after its password was reset. The service role may not delete from
-- auth.sessions itself, so this runs as the function owner. A project without sessions is left alone.
CREATE OR REPLACE FUNCTION public.mt_revoke_user_sessions(target uuid) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
BEGIN
  IF to_regclass('auth.sessions') IS NOT NULL THEN EXECUTE 'DELETE FROM auth.sessions WHERE user_id=$1' USING target; END IF;
END; $$;

REVOKE ALL ON FUNCTION public.mt_replace_recovery_codes(uuid,jsonb), public.mt_recovery_candidates(text), public.mt_consume_recovery_code(bigint), public.mt_recovery_codes_left(uuid), public.mt_revoke_user_sessions(uuid) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.mt_replace_recovery_codes(uuid,jsonb), public.mt_recovery_candidates(text), public.mt_consume_recovery_code(bigint), public.mt_recovery_codes_left(uuid), public.mt_revoke_user_sessions(uuid) TO service_role;

-- An email address nobody has checked can never count as verified. Clearing the flag in the same transaction
-- that changes the address means a change that fails, for example because the address is taken, costs nothing.
CREATE OR REPLACE FUNCTION public.mt_unverify_on_email_change() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
BEGIN
  IF NEW.email IS DISTINCT FROM OLD.email THEN UPDATE public.mt_profiles SET email_verified_at=NULL WHERE id=NEW.id; END IF;
  RETURN NEW;
END; $$;
REVOKE ALL ON FUNCTION public.mt_unverify_on_email_change() FROM PUBLIC, anon, authenticated;
DROP TRIGGER IF EXISTS mt_email_changed ON auth.users;
CREATE TRIGGER mt_email_changed AFTER UPDATE OF email ON auth.users FOR EACH ROW EXECUTE FUNCTION public.mt_unverify_on_email_change();

-- Tours: routes an administrator curates, with the stops in order. Anyone can read a published tour; only
-- administrators can create, change or remove one (the same rule as places). The road route between the stops is
-- worked out once, when the stops are saved, and stored here as a GeoJSON line so the map just draws it.
CREATE TABLE IF NOT EXISTS public.mt_tours (
  id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  name text NOT NULL CHECK(char_length(trim(name)) BETWEEN 3 AND 120),
  name_fr text CHECK(name_fr IS NULL OR char_length(trim(name_fr)) BETWEEN 3 AND 120),
  description text NOT NULL CHECK(char_length(trim(description)) BETWEEN 10 AND 2000),
  description_fr text CHECK(description_fr IS NULL OR char_length(trim(description_fr)) BETWEEN 10 AND 2000),
  -- Ordered: [{"placeId": 12, "minutes": 60}, ...]
  stops jsonb NOT NULL CHECK(jsonb_typeof(stops)='array' AND jsonb_array_length(stops) BETWEEN 2 AND 25),
  published boolean NOT NULL DEFAULT false,
  -- The road line as GeoJSON (a LineString), or NULL while only straight lines are known.
  route_geojson jsonb CHECK(route_geojson IS NULL OR route_geojson->>'type'='LineString'),
  route_distance_m integer CHECK(route_distance_m IS NULL OR route_distance_m >= 0),
  route_duration_s integer CHECK(route_duration_s IS NULL OR route_duration_s >= 0),
  -- A fingerprint of the stops the route was last worked out for, so unchanged stops never ask for a route again.
  route_stops_hash text,
  route_computed_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS mt_tours_published_idx ON public.mt_tours(published, id);

-- Every stop must be a listed place that visitors may go to, with a sensible visit length, and no place may appear twice.
CREATE OR REPLACE FUNCTION mt_private.check_tour() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
DECLARE stop jsonb; seen bigint[] := '{}'; place_access text; place_listed boolean;
BEGIN
  NEW.updated_at := now();
  -- Only changed stops are checked, so a place removed later never blocks renaming or unpublishing the tour.
  IF TG_OP = 'UPDATE' AND NEW.stops IS NOT DISTINCT FROM OLD.stops THEN RETURN NEW; END IF;
  FOR stop IN SELECT value FROM jsonb_array_elements(NEW.stops) LOOP
    -- A stop with a missing or malformed key makes the test NULL, which counts as invalid.
    IF NOT coalesce(
      CASE WHEN jsonb_typeof(stop->'placeId')='number' AND jsonb_typeof(stop->'minutes')='number'
                AND (stop->>'placeId') ~ '^[0-9]{1,15}$' AND (stop->>'minutes') ~ '^[0-9]{1,3}$'
           THEN (stop->>'minutes')::int BETWEEN 5 AND 720 END, false) THEN
      RAISE EXCEPTION 'Each stop needs a place and a visit time of 5 to 720 minutes' USING ERRCODE='22023';
    END IF;
    IF (stop->>'placeId')::bigint = ANY(seen) THEN RAISE EXCEPTION 'A place can appear once in a tour' USING ERRCODE='22023'; END IF;
    seen := seen || (stop->>'placeId')::bigint;
    SELECT access, published INTO place_access, place_listed FROM public.mt_places WHERE id=(stop->>'placeId')::bigint;
    IF NOT FOUND OR NOT coalesce(place_listed, false) THEN RAISE EXCEPTION 'Unknown place in tour' USING ERRCODE='23503'; END IF;
    IF place_access = 'restricted' THEN RAISE EXCEPTION 'A place with restricted access cannot be part of a tour' USING ERRCODE='22023'; END IF;
  END LOOP;
  RETURN NEW;
END; $$;
REVOKE ALL ON FUNCTION mt_private.check_tour() FROM PUBLIC;
DROP TRIGGER IF EXISTS mt_tour_check ON public.mt_tours;
CREATE TRIGGER mt_tour_check BEFORE INSERT OR UPDATE ON public.mt_tours FOR EACH ROW EXECUTE FUNCTION mt_private.check_tour();

ALTER TABLE public.mt_tours ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.mt_tours FROM anon, authenticated;
GRANT SELECT ON public.mt_tours TO anon, authenticated;
GRANT INSERT, UPDATE, DELETE ON public.mt_tours TO authenticated;
GRANT ALL ON public.mt_tours TO service_role;
GRANT USAGE ON SEQUENCE public.mt_tours_id_seq TO authenticated;
DROP POLICY IF EXISTS mt_tours_read ON public.mt_tours;
CREATE POLICY mt_tours_read ON public.mt_tours FOR SELECT TO anon, authenticated USING (published OR (SELECT public.mt_is_admin()));
DROP POLICY IF EXISTS mt_tours_admin_insert ON public.mt_tours;
CREATE POLICY mt_tours_admin_insert ON public.mt_tours FOR INSERT TO authenticated WITH CHECK ((SELECT public.mt_is_admin()));
DROP POLICY IF EXISTS mt_tours_admin_update ON public.mt_tours;
CREATE POLICY mt_tours_admin_update ON public.mt_tours FOR UPDATE TO authenticated USING ((SELECT public.mt_is_admin())) WITH CHECK ((SELECT public.mt_is_admin()));
DROP POLICY IF EXISTS mt_tours_admin_delete ON public.mt_tours;
CREATE POLICY mt_tours_admin_delete ON public.mt_tours FOR DELETE TO authenticated USING ((SELECT public.mt_is_admin()));

SELECT pg_advisory_xact_lock(23092026);
DO $seed$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM public.mt_metadata WHERE key = 'catalogue_seeded') THEN
