    FROM jsonb_to_recordset('[{"id":1,"name":"Le Petibonum","type":"restaurant","lat":14.7015273,"lng":-61.181476,"location":"Le Carbet","description":"A small restaurant on a private black-sand beach in Le Carbet, on the Caribbean-facing north coast. The cooking blends different influences, and there is a rum bar plus sun loungers and showers for a day by the sea.","description_fr":"Un petit restaurant installé sur une plage privée au sable noir, au Carbet, sur la côte caraïbe du nord. La cuisine est métissée ; on y trouve aussi un bar à rhum, ainsi que des transats et des douches pour profiter de la journée au bord de la mer.","tags":["Beachfront","Creole","Seafood","Casual"],"sources":[{"url":"https://petibonum.com/","title":"Le Petibonum","fields":["Name","Town","Description","Social media"],"checkedAt":"2026-10-02"},{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/restaurant-le-petibonum","title":"Comité Martiniquais du Tourisme","fields":["Name","Town","Map point","Address","Telephone","Website","Type","Payment","Languages spoken","Services","Opening hours"],"checkedAt":"2026-10-02"}],"access":"unknown","published":true,"details":{"from":{"kind":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/restaurant-le-petibonum","checkedAt":"2026-10-02"},"phone":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/restaurant-le-petibonum","checkedAt":"2026-10-02"},"address":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/restaurant-le-petibonum","checkedAt":"2026-10-02"},"payment":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/restaurant-le-petibonum","checkedAt":"2026-10-02"},"website":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/restaurant-le-petibonum","checkedAt":"2026-10-02"},"facebook":{"url":"https://petibonum.com/","checkedAt":"2026-10-02"},"services":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/restaurant-le-petibonum","checkedAt":