_Cl%C3%A9ment.jpg","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0/"},"sources":[{"url":"https://www.rhum-clement.com/home/lexperience/","title":"Habitation Clément","fields":["Description","Listed hours","Social media"],"checkedAt":"2026-10-02"},{"url":"https://www.martinique.org/fr/que-faire/culture-patrimoine/habitation-clement","title":"Comité Martiniquais du Tourisme","fields":["Name","Town","Map point","Address","Telephone","Website","Payment","Languages spoken","Opening hours"],"checkedAt":"2026-10-02"}],"access":"unknown","published":true,"details":{"from":{"phone":{"url":"https://www.martinique.org/fr/que-faire/culture-patrimoine/habitation-clement","checkedAt":"2026-10-02"},"address":{"url":"https://www.martinique.org/fr/que-faire/culture-patrimoine/habitation-clement","checkedAt":"2026-10-02"},"payment":{"url":"https://www.martinique.org/fr/que-faire/culture-patrimoine/habitation-clement","checkedAt":"2026-10-02"},"website":{"url":"https://www.martinique.org/fr/que-faire/culture-patrimoine/habitation-clement","checkedAt":"2026-10-02"},"facebook":{"url":"https://www.rhum-clement.com/home/lexperience/","checkedAt":"2026-10-02"},"instagram":{"url":"https://www.rhum-clement.com/home/lexperience/","checkedAt":"2026-10-02"},"languages":{"url":"https://www.martinique.org/fr/que-faire/culture-patrimoine/habitation-clement","checkedAt":"2026-10-02"}},"phone":"+596 596 54 75 51","address":"Domaine de L''acajou, 97240 Le François","payment":["Cartes bancaires","Chèques bancaires et postaux"],"website":"https://www.habitation-clement.fr/","facebook":"https://www.facebook.com/rhumclement.fr/","instagram":"https://www.instagram.com/rhumclement/","languages":["Anglais","Français"]},"opening_periods":[{"day":0,"opens":540,"closes":1110},{"day":1,"opens":540,"closes":1110},{"day":2,"opens":540,"closes":1110},{"day":3,"opens":540,"closes":1110},{"day":4,"opens":540,"closes":1110},{"day":5,"opens":540,"closes":1110},{"day":6,"opens":540,"closes":1110}],"hours_source":"https://www.martinique.org/fr/que-faire/culture-patrimoine/habitation-clement","hours_updated_at":"2026-10-03T01:31:34.528663+00:00"},{"id":3,"name":"Jardin de Balata","type":"activity","lat":14.6721053,"lng":-61.09136,"location":"Fort-de-France","description":"A botanical garden on the Route de la Trace, a few minutes from Fort-de-France, created in 1982 around a historic Creole house. It holds more than 3,000 tropical species, including rare palms, hibiscus and heliconias, and is a good place to watch birds. It carries the French Jardin Remarquable label.","description_fr":"Un jardin botanique créé en 1982 autour d’une ancienne maison créole, installé le long de la Route de la Trace, non loin de Fort-de-France. On y croise plus de 3 000 espèces tropicales (palmiers rares, hibiscus, héliconias) et de nombreux oiseaux. Le jardin est classé Jardin remarquable.","hours":"09:00–18:00 · Last entry / Dernière entrée 16:30","tags":["Nature","Botanical","Family Friendly","Scenic"],"image":"/photos/balata.jpg","photo_credit":{"author":"Box-Off-Dreams, Julie","caption":"Jardin de Balata · 2008","license":"Public domain","sourceUrl":"https://commons.wikimedia.org/wiki/File:Jardin_de_Balata.jpg","licenseUrl":"https://commons.wikimedia.org/wiki/File:Jardin_de_Balata.jpg"},"sources":[{"url":"https://www.jardindebalata.fr/horaires-et-animations","title":"Jardin de Balata","fields":["Name","Town","Listed hours","Social media"],"checkedAt":"2026-10-02"},{"url":"https://www.martinique.org/fr/que-faire/sites-naturels-publics/jardin-de-balata","title":"Comité Martiniquais du Tourisme","fields":["Name","Town","Map point","Address","Telephone","Website","Price range","Payment","Languages spoken","Services","Accessibility","Opening hours"],"checkedAt":"2026-10-02"}],"access":"unknown","published":true,"details":{"from":{"phone":{"url":"https://www.martinique.org/fr/que-faire/sites-naturels-publics/jardin-de-balata","checkedAt":"2026-10-02"},"address":{"url":"https://www.martiniqu