://www.westparadise.fr/","checkedAt":"2026-10-02"}},"phone":"+596 596 72 42 32","facebook":"https://www.facebook.com/Westparadise972","instagram":"https://www.instagram.com/west_paradise_martinique/"}},{"id":18,"name":"Hippopotamus La Galleria","type":"restaurant","lat":14.6062,"lng":-61.021,"location":"Le Lamentin","description":"A French-style steakhouse in Le Lamentin built around beef, including cuts of French origin, with a wide menu that follows the seasons. It is set up for lunch or dinner with family or friends.","description_fr":"Une steak house à la française au Lamentin, centrée sur le bœuf, notamment des pièces d’origine française, avec une carte étendue qui suit les saisons. Un cadre pensé pour un déjeuner ou un dîner en famille ou entre amis.","tags":["Steakhouse","French","Classy","Burgers","Le Lamentin"],"sources":[{"url":"https://www.hippopotamus.fr/nos-restaurants/hippopotamus-martinique-la-galleria","title":"Hippopotamus","fields":["Name","Town","Description","Telephone","Social media"],"checkedAt":"2026-10-02"}],"access":"unknown","published":true,"details":{"from":{"phone":{"url":"https://www.hippopotamus.fr/nos-restaurants/hippopotamus-martinique-la-galleria","checkedAt":"2026-10-02"},"facebook":{"url":"https://www.hippopotamus.fr/nos-restaurants/hippopotamus-martinique-la-galleria","checkedAt":"2026-10-02"},"instagram":{"url":"https://www.hippopotamus.fr/nos-restaurants/hippopotamus-martinique-la-galleria","checkedAt":"2026-10-02"}},"phone":"+596 596 54 62 66","facebook":"https://fr-fr.facebook.com/Hippopotamus/","instagram":"https://www.instagram.com/hippopotamus_steakhouse/"}},{"id":19,"name":"Torii Sushi","type":"restaurant","lat":14.6115,"lng":-61.0255,"location":"Le Lamentin","description":"A calm, bright sushi restaurant that blends Japanese cooking with a Brazilian touch. The sushi master prepares his specialities in view of guests as they enter. The name refers to the torii, the Japanese gate between the everyday and the spiritual world.","description_fr":"Un restaurant de sushis calme et lumineux, mêlant cuisine japonaise et touche brésilienne. Dès l’entrée, le maître sushi prépare ses spécialités devant les clients. Torii est le nom de la porte japonaise qui sépare le monde profane du monde spirituel.","tags":["Sushi","Japanese","Classy","Asian Fusion"],"sources":[{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/torii-sushi","title":"Martinique Tourisme","fields":["Name","Town","Description","Address","Telephone","Website","Price range","Type","Payment","Languages spoken"],"checkedAt":"2026-10-02"}],"access":"unknown","published":true,"details":{"from":{"kind":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/torii-sushi","checkedAt":"2026-10-02"},"phone":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/torii-sushi","checkedAt":"2026-10-02"},"address":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/torii-sushi","checkedAt":"2026-10-02"},"payment":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/torii-sushi","checkedAt":"2026-10-02"},"website":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/torii-sushi","checkedAt":"2026-10-02"},"languages":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/torii-sushi","checkedAt":"2026-10-02"},"priceRange":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/torii-sushi","checkedAt":"2026-10-02"}},"kind":["Cuisine du Monde"],"phone":"+596 596 67 28 47","address":"Jambette Village, 97232 Le Lamentin","payment":["Cartes bancaires","Espèces","Tickets restaurant"],"website":"https://www.toriisushi.fr/","languages":["Anglais","Français"],"priceRange":"8–135 €"}},{"id":20,"name":"McDonald''s","type":"restaurant","lat":14.6111,"lng":-61.024,"location":"Le Lamentin","description":"This entry from the original catalogue is awaiting verification before publication.","description_fr":"Cette entrée du catalogue initial reste à vérifier avant publication.","tags":["Fast Food","Burgers","Quick Bite","Family Friendly"],"sources":[],"access":"unknown","published":false},{"id":21,"name":"Bokay Burger (BKB)","type":"restaurant","lat":14.5684,"lng":-60.985,"location":"Ducos","description":"This entry from the original catalogue is awaiting verification before publication.","description_fr":"Cette entrée du catalogue initial reste à vérifier avant publication.","tags":["BKB","Local Burgers","Fried Chicken","Quick Bite","Local Favorite"],"sources":[],"access":"unknown","published":false},{"id":22,"name":"Chez Fredo","type":"restaurant","lat":14.4682,"lng":-60.9295,"location":"Sainte-Luce","description":"This entry from the original catalogue is awaiting verification before publication.","description_fr":"Cette entrée du catalogue initial reste à vérifier avant publication.","tags":["Creole","Live Music","Beachside","Traditional","Local Favorite","South of Island"],"sources":[],"access":"unknown","published":false},{"id":23,"name":"Le Balaou","type":"restaurant","lat":14.4681,"lng":-60.9248,"location":"Sainte-Luce","description":"This entry from the original catalogue is awaiting verification before publication.","description_fr":"Cette entrée du catalogue initial reste à vérifier avant publication.","tags":["Seafood","Beachside","Local","Cocktails","South of Island"],"sources":[],"access":"unknown","published":false},{"id":24,"name":"La Dunette","type":"restaurant","lat":14.435,"lng":-60.8814,"location":"Sainte-Anne","description":"A waterfront hotel, bar and restaurant in Sainte-Anne with a pontoon, a deck with sun loungers and panoramic views. The kitchen serves French and local dishes, with Sunday brunch and house cocktails, and there is live music from Thursday to Saturday evenings, especially in season. Some rooms look out over the sea.","description_fr":"Un hôtel, bar et restaurant en bord de mer à Sainte-Anne, avec ponton, deck et transats face à une vue panoramique. La cuisine mêle plats français et locaux, avec brunch le dimanche et cocktails maison, et de la musique live est proposée du jeudi au samedi soir, surtout en saison. Certaines chambres ont vue sur la mer.","tags":["Waterfront","Cocktails","South of Island","Creole","Sunset Views"],"sources":[{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/la-dunette","title":"Martinique Tourisme","fields":["Name","Town","Description","Address","Telephone","Website","Social media","Price range","Type","Payment","Languages spoken","Services","Opening hours"],"checkedAt":"2026-10-02"}],"access":"unknown","published":true,"details":{"from":{"kind":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/la-dunette","checkedAt":"2026-10-02"},"phone":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/la-dunette","checkedAt":"2026-10-02"},"address":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/la-dunette","checkedAt":"2026-10-02"},"payment":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/la-dunette","checkedAt":"2026-10-02"},"website":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/la-dunette","checkedAt":"2026-10-02"},"facebook":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/la-dunette","checkedAt":"2026-10-02"},"services":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/la-dunette","checkedAt":"2026-10-02"},"languages":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/la-dunette","checkedAt":"2026-10-02"},"priceRange":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/la-dunette","checkedAt":"2026-10-02"}},"kind":["Restaurant de plage"],"phone":"+596 596 76 73 90","address":"Avenue Jean Marie Tjibaou, 97227 Sainte-Anne","payment":["Cartes bancaires","Chèques vacances","Tickets restaurant"],"website":"https://www.ladunette.com/","facebook":"https://www.facebook.com/ladunettemartinique","services":["Point wifi"],"languages":["Anglais","Français"],"priceRange":"16–25 €"},"opening_periods":[{"day":0,"opens":450,"closes":1440},{"day":1,"opens":450,"closes":1440},{"day":2,"opens":450,"closes":1440},{"day":3,"opens":450,"closes":1440},{"day":4,"opens":450,"closes":1440},{"day":5,"opens":450,"closes":1440},{"day":6,"opens":450,"closes":1440}],"hours_source":"https://www.martinique.org/fr/bars-restaurants/restaurants/la-dunette","hours_updated_at":"2026-10-03T01:31:36.88083+00:00"},{"id":25,"name":"1643","type":"restaurant","lat":14.731364,"lng":-61.177416,"location":"Le Carbet","description":"A restaurant at Anse Latouche with a large terrace facing the garden. The chef cooks creatively with Creole touches and local flavours, with dishes such as fish in the Tahitian style or roasted blue crayfish, and the mood turns more romantic in the evening.","description_fr":"Un restaurant installé à l’Anse Latouche, avec une vaste terrasse tournée vers le jardin. Le chef propose une cuisine inventive, de tonalité créole et ancrée dans le terroir : poisson à la tahitienne, écrevisse bleue rôtie… Le soir, les lumières tamisées donnent à la salle un air plus romantique.","tags":["Fine Dining"],"sources":[{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/1643","title":"Comité Martiniquais du Tourisme","fields":["Name","Town","Category","Description","Map point","Address","Telephone","Website","Price range","Type","Payment","Languages spoken","Services","Opening hours"],"checkedAt":"2026-10-02"}],"access":"unknown","published":true,"details":{"from":{"kind":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/1643","checkedAt":"2026-10-02"},"phone":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/1643","checkedAt":"2026-10-02"},"address":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/1643","checkedAt":"2026-10-02"},"payment":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/1643","checkedAt":"2026-10-02"},"website":{"url":"https://www.martinique.