quais du Tourisme","fields":["Name","Town","Category","Description","Map point","Address","Telephone","Social media","Price range","Type","Payment","Languages spoken","Opening hours"],"checkedAt":"2026-10-02"}],"access":"unknown","published":true,"details":{"from":{"kind":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/agap-peyi","checkedAt":"2026-10-02"},"phone":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/agap-peyi","checkedAt":"2026-10-02"},"address":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/agap-peyi","checkedAt":"2026-10-02"},"payment":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/agap-peyi","checkedAt":"2026-10-02"},"facebook":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/agap-peyi","checkedAt":"2026-10-02"},"instagram":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/agap-peyi","checkedAt":"2026-10-02"},"languages":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/agap-peyi","checkedAt":"2026-10-02"},"priceRange":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/agap-peyi","checkedAt":"2026-10-02"}},"kind":["Table d''hôtes"],"phone":"+596 696 96 96 25","address":"Morne Pitault, 97240 Le François","payment":["Cartes bancaires","Espèces"],"facebook":"https://www.facebook.com/p/agap_peyi_a-100063911630749","instagram":"https://instagram.com/agap_peyi_a","languages":["Anglais","Français"],"priceRange":"68 €"},"opening_periods":[{"day":4,"opens":720,"closes":900},{"day":4,"opens":1170,"closes":1320},{"day":5,"opens":720,"closes":900},{"day":5,"opens":1170,"closes":1320},{"day":6,"opens":1170,"closes":1320}],"hours_source":"https://www.martinique.org/fr/bars-restaurants/restaurants/agap-peyi","hours_updated_at":"2026-10-03T01:31:37.442495+00:00"},{"id":27,"name":"Caribbean Food","type":"restaurant","lat":14.4648074,"lng":-60.928477,"location":"Sainte-Luce","description":"A beach restaurant and bar on Gros Raisin beach in Sainte-Luce, serving homemade, updated Creole cooking from a slate menu that follows the season, with dishes such as lobster, conch, tuna tartare and marlin. There are loungers facing the sea, cocktails, local draught beer, cod fritters, crêpes and ice cream.","description_fr":"Un restaurant-bar de plage à Sainte-Luce, à Gros Raisin, face à la mer. Cuisine créole réinventée, uniquement faite maison, annoncée à l’ardoise selon les arrivages et les saisons : langouste, lambi, tartare de thon ou marlin. On profite aussi des transats face à la mer, de cocktails, de bière locale à la pression, d’accras de morue, de crêpes et de glaces.","tags":["Beachfront"],"sources":[{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/caribbean-food","title":"Comité Martiniquais du Tourisme","fields":["Name","Town","Category","Description","Map point","Address","Telephone","Social media","Price range","Type","Payment","Languages spoken","Services","Opening hours"],"checkedAt":"2026-10-02"}],"access":"unknown","published":true,"details":{"from":{"kind":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/caribbean-food","checkedAt":"2026-10-02"},"phone":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/caribbean-food","checkedAt":"2026-10-02"},"address":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/caribbean-food","checkedAt":"2026-10-02"},"payment":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/caribbean-food","checkedAt":"2026-10-02"},"facebook":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/caribbean-food","checkedAt":"2026-10-02"},"services":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/caribbean-food","checkedAt":"2026-10-02"},"languages":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/caribbean-food","checkedAt":"2026-10-02"},"priceRange":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/caribbean-food","checkedAt":"2026-10-02"}},"kind":["Restaurant de plage"],"phone":"+596 696 18 26 94","address":"plage de gros raisins, deuxième anse gros raisins, 97228 Sainte-Luce","payment":["Cartes bancaires","Espèces"],"facebook":"https://www.facebook.com/caribbeanfood.fwi","services":["Point wifi"],"languages":["Anglais","Espagnol","Français"],"priceRange":"7–22 €"},"opening_periods":[{"day":0,"opens":690,"closes":1080},{"day":1,"opens":690,"closes":1290},{"day":3,"opens":690,"closes":1290},{"day":4,"opens":690,"closes":1290},{"day":5,"opens":690,"closes":1290},{"day":6,"opens":690,"closes":1290}],"hours_source":"https://www.martinique.org/fr/bars-restaurants/restaurants/caribbean-food","hours_updated_at":"2026-10-03T01:31:37.719531+00:00"},{"id":28,"name":"Chez Gracieuse","type":"restaurant","lat":14.4358023,"lng":-60.827457,"location":"Sainte-Anne","description":"A Creole restaurant in Sainte-Anne with a warm, friendly atmosphere and a clear view of the sea. On Sundays there is an all-you-can-eat buffet with live music or a DJ.","description_fr":"Un restaurant créole à Sainte-Anne, à l’ambiance chaleureuse et conviviale, avec une vue dégagée sur la mer. Le dimanche, un buffet à volonté est proposé avec animation musicale live ou DJ.","tags":["Creole"],"sources":[{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/chez-gracieuse","title":"Comité Martiniquais du Tourisme","fields":["Name","Town","Category","Description","Map point","Address","Telephone","Website","Social media","Type","Payment","Languages spoken","Opening hours"],"checkedAt":"2026-10-02"}],"access":"unknown","published":true,"details":{"from":{"kind":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/chez-gracieuse","checkedAt":"2026-10-02"},"phone":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/chez-gracieuse","checkedAt":"2026-10-02"},"address":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/chez-gracieuse","checkedAt":"2026-10-02"},"payment":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/chez-gracieuse","checkedAt":"2026-10-02"},"website":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/chez-gracieuse","checkedAt":"2026-10-02"},"facebook":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/chez-gracieuse","checkedAt":"2026-10-02"},"languages":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/chez-gracieuse","checkedAt":"2026-10-02"}},"kind":["Cuisine traditionnelle"],"phone":"+596 596 76 93 10","address":"Cap Chevalier, 97227 Sainte-Anne","payment":["Cartes bancaires","Chèques bancaires et postaux","Chèques vacances","Tickets restaurant"],"website":"https://www.taxi-cap.com/","facebook":"https://www.facebook.com/RestaurantChezGracieuse","languages":["Anglais","Français"]},"opening_periods":[{"day":0,"opens":540,"closes":1020},{"day":1,"opens":540,"closes":1020},{"day":2,"opens":540,"closes":1020},{"day":3,"opens":540,"closes":1020},{"day":4,"opens":540,"closes":1020},{"day":5,"opens":540,"closes":1020},{"day":6,"opens":540,"closes":1020}],"hours_source":"https://www.martinique.org/fr/bars-restaurants/restaurants/chez-gracieuse","hours_updated_at":"2026-10-03T01:31:37.991123+00:00"},{"id":29,"name":"Djol Dou","type":"restaurant","lat":14.60402396,"lng":-61.071832,"location":"Fort-de-France","description":"A small family restaurant serving Antillean home cooking on rue Garnier Pagès, one of the most colourful and flower-lined streets of Fort-de-France. A good stop at lunchtime for slow-simmered dishes.","description_fr":"Un petit restaurant familial de cuisine antillaise, rue Garnier Pagès, l’une des rues les plus colorées et fleuries de Fort-de-France. Une bonne halte le midi pour des plats mijotés.","tags":["Creole"],"sources":[{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/djol-dou","title":"Comité Martiniquais du Tourisme","fields":["Name","Town","Category","Description","Map point","Address","Telephone","Social media","Price range","Type","Payment"],"checkedAt":"2026-10-02"}],"access":"unknown","published":true,"details":{"from":{"kind":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/djol-dou","checkedAt":"2026-10-02"},"phone":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/djol-dou","checkedAt":"2026-10-02"},"address":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/djol-dou","checkedAt":"2026-10-02"},"payment":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/djol-dou","checkedAt":"2026-10-02"},"facebook":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/djol-dou","checkedAt":"2026-10-02"},"priceRange":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/djol-dou","checkedAt":"2026-10-02"}},"kind":["Cuisine traditionnelle"],"phone":"+596 596 63 10 84","address":"25 Rue Garnier Pages, 97200 Fort-De-France","payment":["Cartes bancaires","Espèces"],"facebook":"https://www.facebook.com/DjolDouRestaurant","priceRange":"3–29 €"}},{"id":30,"name":"Domb''ox- Bar À Dombrés","type":"restaurant","lat":14.6039946,"lng":-61.070188,"location":"Fort-de-France","description":"A food concept built around dombrés, a signature dish of Martinican and Caribbean cooking. Meals can be eaten in, taken away, delivered or collected at a drive-through, in a format that mixes tradition with a modern touch.","description_fr":"Un concept de restauration consacré aux dombrés, un plat typique de la cuisine martiniquaise comme de la cuisine caribéenne. On peut déguster sur place, emporter, se faire livrer ou commander au volant, dans un format qui allie tradition et modernité.","tags":["Creole"],"sources":[{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/dombox-bar-dombres","title":"Comité Martiniquais du Tourisme","fields":["Name","Town","Category","Description","Map point","Address","Telephone","Social media","Opening hours","Price range","Type","Payment"],"checkedAt":"2026-10-02"}],"access":"unknown","published":true,"details":{"from":{"kind":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/dombox-bar-dombres","checkedAt":"2026-10-02"},"phone":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/dombox-bar-dombres","checkedAt":"2026-10-02"},"address":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/dombox-bar-dombres","checkedAt":"2026-10-02"},"payment":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/dombox-bar-dombres","checkedAt":"2026-10-02"},"facebook":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/dombox-bar-dombres","checkedAt":"2026-10-02"},"hoursText":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/dombox-bar-dombres","checkedAt":"2026-10-02"},"instagram":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/dombox-bar-dombres","checkedAt":"2026-10-02"},"priceRange":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/dombox-bar-dombres","checkedAt":"2026-10-02"}},"kind":["Cuisine traditionnelle"],"phone":"+596 696 61 20 73","address":"52 rue Victor Hugo, 97200 Fort-De-France","payment":["Cartes bancaires","Espèces","Tickets restaurant"],"facebook":"https://www.facebook.com/dombox.mq","hoursText":"Lundi : À partir de 11h30, À partir de 14h30\nMardi : À partir de 11h30, À partir de 14h30\nMercredi : À partir de 11h30, À partir de 14h30\nJeudi : À partir de 11h30, À partir de 14h30\nVendredi : À partir de 11h30, À partir de 14h30\nSamedi : À partir de 11h30, À partir de 14h00\nDimanche : À partir de 11h30, À partir de 14h00","instagram":"https://instagram.com/dombox.mq","priceRange":"6,50–19 €"}},{"id":31,"name":"Effet Mer","type":"restaurant","lat":14.6988364,"lng":-61.180661,"location":"Le Carbet","description":"A seafront restaurant at Plage du Coin in Le Carbet on the north Caribbean coast, built around pierrades, where food is cooked on a hot stone. Its setting is described as paradise-like, and the menu aims at many different tastes.","description_fr":"Un restaurant en bord de mer à Plage du Coin, au Carbet, sur la côte nord-caraïbe, bâti autour des pierrades, avec cuisson sur pierre chaude. Son cadre est qualifié de paradisiaque et la carte vise des goûts très différents.","tags":["Beachfront"],"sources":[{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/effet-mer","title":"Comité Martiniquais du Tourisme","fields":["Name","Town","Category","Description","Map point","Address","Telephone","Price range","Type","Payment","Languages spoken","Services","Opening hours"],"checkedAt":"2026-10-02"}],"access":"unknown","published":true,"details":{"from":{"kind":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/effet-mer","checkedAt":"2026-10-02"},"phone":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/effet-mer","checkedAt":"2026-10-02"},"address":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/effet-mer","checkedAt":"2026-10-02"},"payment":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/effet-mer","checkedAt":"2026-10-02"},"services":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/effet-mer","checkedAt":"2026-10-02"},"languages":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/effet-mer","checkedAt":"2026-10-02"},"priceRange":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/effet-mer","checkedAt":"2026-10-02"}},"kind":["Restaurant de plage"],"phone":"+596 696 35 44 84","address":"Plage du Coin, 97221 Le Carbet","payment":["Cartes bancaires","Espèces","Tickets restaurant"],"services":["Point wifi"],"languages":["Anglais","Français"],"priceRange":"15–24 €"},"opening_periods":[{"day":0,"opens":720,"closes":1140},{"day":1,"opens":720,"closes":1140},{"day":3,"opens":720,"closes":1140},{"day":5,"opens":720,"closes":1320},{"day":6,"opens":720,"closes":1320}],"hours_source":"https://www.martinique.org/fr/bars-restaurants/restaurants/effet-mer","hours_updated_at":"2026-10-03T01:31:38.557221+00:00"},{"id":32,"name":"Galanga Fish Bar","type":"restaurant","lat":14.6239197,"lng":-61.0748038,"location":"Fort-de-France","description":"A restaurant in tropical greenery in the hills of Fort-de-France whose menu rests on local farming and fishing. It describes its carte as fully organic and local, with fish served in many ways, including ceviche, tataki, carpaccio and fish and chips, often in bowls.","description_fr":"Un restaurant niché dans la verdure tropicale sur les hauteurs de Fort-de-France, dont la carte s’appuie sur l’agriculture et la pêche locales. Il présente sa carte comme entièrement bio et locale, avec du poisson décliné de multiples façons : ceviche, tataki, carpaccio, fish and chips, souvent servis en bowl.","tags":["International"],"sources":[{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/galanga-fish-bar","title":"Comité Martiniquais du Tourisme","fields":["Name","Town","Category","Description","Map point","Address","Telephone","Price range","Type","Payment","Languages spoken"],"checkedAt":"2026-10-02"}],"access":"unknown","published":true,"details":{"from":{"kind":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/galanga-fish-bar","checkedAt":"2026-10-02"},"phone":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/galanga-fish-bar","checkedAt":"2026-10-02"},"address":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/galanga-fish-bar","checkedAt":"2026-10-02"},"payment":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/galanga-fish-bar","checkedAt":"2026-10-02"},"languages":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/galanga-fish-bar","checkedAt":"2026-10-02"},"priceRange":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/galanga-fish-bar","checkedAt":"2026-10-02"}},"kind":["Cuisine du Monde"],"phone":"+596 696 24 51 26","address":"31 Route de L’Union, 97200 Fort-De-France","payment":["Cartes bancaires","Chèques bancaires et postaux","Espèces","Tickets restaurant","Virement bancaire"],"languages":["Anglais","Espagnol","Français"],"priceRange":"35–45 €"}},{"id":33,"name":"Habitation Ceron","type":"restaurant","lat":14.8308701,"lng":-61.219711,"location":"Le Prêcheur","description":"A restaurant set in tropical forest on the old estate''s case-nègre street, between a river and the sea. Specialities include crayfish caught at night and cooked à la plancha, plus fish and meat menus with sides made from the estate''s own produce. In the afternoon it serves homemade sweets in the shade of the open-sided shelters.","description_fr":"Un restaurant en pleine forêt tropicale, entre rivière et bord de mer, dans l’ancienne rue case-nègre de l’habitation. La maison propose notamment des écrevisses pêchées la nuit et grillées à la plancha, ainsi que des menus de poisson et de viande, avec des légumes et fruits de l’habitation. Le goûter se prend à l’ombre des carbets.","tags":["Creole"],"sources":[{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/habitation-ceron","title":"Comité Martiniquais du Tourisme","fields":["Name","Town","Category","Description","Map point","Address","Telephone","Website","Social media","Price range","Type","Payment","Languages spoken","Services","Opening hours"],"checkedAt":"2026-10-02"}],"access":"unknown","published":true,"details":{"from":{"kind":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/habitation-ceron","checkedAt":"2026-10-02"},"phone":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/habitation-ceron","checkedAt":"2026-10-02"},"address":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/habitation-ceron","checkedAt":"2026-10-02"},"payment":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/habitation-ceron","checkedAt":"2026-10-02"},"website":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/habitation-ceron","checkedAt":"2026-10-02"},"facebook":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/habitation-ceron","checkedAt":"2026-10-02"},"services":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/habitation-ceron","checkedAt":"2026-10-02"},"languages":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/habitation-ceron","checkedAt":"2026-10-02"},"priceRange":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/habitation-ceron","checkedAt":"2026-10-02"}},"kind":["Cuisine traditionnelle"],"phone":"+596 596 48 27 53","address":"Habitation Ceron, Quartier Anse Ceron, 97250 Le Precheur","payment":["Cartes bancaires","Chèques vacances","Tickets restaurant"],"website":"https://www.habitation-ceron.com/","facebook":"https://www.facebook.com/habitationceron","services":["Point wifi"],"languages":["Allemand","Anglais","Espagnol","Français"],"priceRange":"50–75 €"},"opening_periods":[{"day":0,"opens":570,"closes":1020},{"day":1,"opens":570,"closes":1020},{"day":2,"opens":570,"closes":1020},{"day":3,"opens":570,"closes":1020},{"day":4,"opens":570,"closes":1020},{"day":5,"opens":570,"closes":1020},{"day":6,"opens":570,"closes":1020}],"hours_source":"https://www.martinique.org/fr/bars-restaurants/restaurants/habitation-ceron","hours_updated_at":"2026-10-03T01:31:38.973297+00:00"},{"id":34,"name":"Havana Café","type":"restaurant","lat":14.5433748,"lng":-61.042564,"location":"Les Trois-Îlets","description":"A café-restaurant in the Village Créole that serves all day, from breakfast through lunch, afternoon snacks and aperitif cocktails to dinner. The menu runs from salads and fresh fish tartares to grills, savoury and sweet crêpes, burgers and fajitas, with a wine list.","description_fr":"Un café-restaurant du Village Créole qui sert en continu, du petit déjeuner au dîner, en passant par le déjeuner, le goûter et l’apéro. La carte va des salades composées et tartares de poisson frais aux grillades, galettes et crêpes, burgers et fajitas, avec une carte des vins.","tags":["International"],"sources":[{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/havana-cafe","title":"Comité Martiniquais du Tourisme","fields":["Name","Town","Category","Description","Map point","Address","Telephone","Price range","Type","Payment","Languages spoken","Opening hours"],"checkedAt":"2026-10-02"}],"access":"unknown","published":true,"details":{"from":{"kind":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/havana-cafe","checkedAt":"2026-10-02"},"phone":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/havana-cafe","checkedAt":"2026-10-02"},"address":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/havana-cafe","checkedAt":"2026-10-02"},"payment":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/havana-cafe","checkedAt":"2026-10-02"},"languages":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/havana-cafe","checkedAt":"2026-10-02"},"priceRange":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/havana-cafe","checkedAt":"2026-10-02"}},"kind":["Cuisine du Monde"],"phone":"+596 596 66 15 93","address":"Rue du Chacha, 97229 Les Trois-Ilets","payment":["Cartes bancaires","Espèces"],"languages":["Français"],"priceRange":"15–22 €"},"opening_periods":[{"day":0,"opens":540,"closes":1410},{"day":1,"opens":540,"closes":1410},{"day":2,"opens":540,"closes":1410},{"day":3,"opens":540,"closes":1410},{"day":4,"opens":540,"closes":1410},{"day":5,"opens":540,"closes":1410},{"day":6,"opens":540,"closes":1440}],"hours_source":"https://www.martinique.org/fr/bars-restaurants/restaurants/havana-cafe","hours_updated_at":"2026-10-03T01:31:39.247001+00:00"},{"id":35,"name":"Kai Nono","type":"restaurant","lat":14.6195696,"lng":-60.890579,"location":"Le François","description":"A seafood and local-cuisine restaurant in the centre of Le François, looking over the port. Typical dishes include accras, fish blaff and shrimp fricassée, served in a relaxed setting with ti-punch and house cocktails.","description_fr":"Un restaurant de fruits de mer et de cuisine locale au cœur du François, avec vue sur le port. On y trouve notamment des acras, du blaff de poisson et de la fricassée de crevettes, dans une ambiance décontractée, avec ti-punch et cocktails maison.","tags":["Creole"],"sources":[{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/kai-nono","title":"Comité Martiniquais du Tourisme","fields":["Name","Town","Category","Description","Map point","Address","Telephone","Price range","Type","Payment","Languages spoken","Opening hours"],"checkedAt":"2026-10-02"}],"access":"unknown","published":true,"details":{"from":{"kind":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/kai-nono","checkedAt":"2026-10-02"},"phone":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/kai-nono","checkedAt":"2026-10-02"},"address":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/kai-nono","checkedAt":"2026-10-02"},"payment":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/kai-nono","checkedAt":"2026-10-02"},"languages":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/kai-nono","checkedAt":"2026-10-02"},"priceRange":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/kai-nono","checkedAt":"2026-10-02"}},"kind":["Fruits de mer"],"phone":"+596 596 54 32 76","address":"Route du Club Nautique, 97240 Le François","payment":["Cartes bancaires","Espèces","Virement bancaire"],"languages":["Français"],"priceRange":"8–25 €"},"opening_periods":[{"day":0,"opens":630,"closes":1320},{"day":2,"opens":630,"closes":1080},{"day":3,"opens":630,"closes":1080},{"day":4,"opens":630,"closes":1320},{"day":5,"opens":630,"closes":1320},{"day":6,"opens":630,"closes":1320}],"hours_source":"https://www.martinique.org/fr/bars-restaurants/restaurants/kai-nono","hours_updated_at":"2026-10-03T01:31:39.530628+00:00"},{"id":36,"name":"Kay Ali","type":"restaurant","lat":14.6093724,"lng":-61.084752,"location":"Fort-de-France","description":"A restaurant in a handsome colonial house on the edge of Fort-de-France. The chef cooks refined market cuisine from fresh ingredients, inventive but rooted in tradition, in a cosy setting, and the weekend brings brunch.","description_fr":"Un restaurant installé dans une belle demeure coloniale en périphérie de Fort-de-France. Le chef propose une cuisine du marché raffinée à partir de produits frais, inventive tout en restant ancrée dans la tradition, dans un cadre cosy, avec un brunch le week-end.","tags":["Fine Dining"],"sources":[{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/kay-ali","title":"Comité Martiniquais du Tourisme","fields":["Name","Town","Category","Description","Map point","Address","Telephone","Price range","Type","Payment","Languages spoken","Opening hours"],"checkedAt":"2026-10-02"}],"access":"unknown","published":true,"details":{"from":{"kind":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/kay-ali","checkedAt":"2026-10-02"},"phone":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/kay-ali","checkedAt":"2026-10-02"},"address":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/kay-ali","checkedAt":"2026-10-02"},"payment":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/kay-ali","checkedAt":"2026-10-02"},"languages":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/kay-ali","checkedAt":"2026-10-02"},"priceRange":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/kay-ali","checkedAt":"2026-10-02"}},"kind":["Restaurant gastronomique - cuisine raffinée"],"phone":"+596 596 50 17 72","address":"145 avenue condorcet, 97200 Fort-De-France","payment":["Cartes bancaires","Espèces"],"languages":["Français"],"priceRange":"8–26 €"},"opening_periods":[{"day":2,"opens":720,"closes":870},{"day":3,"opens":720,"closes":870},{"day":4,"opens":720,"closes":840},{"day":4,"opens":1170,"closes":1320},{"day":5,"opens":720,"closes":840},{"day":5,"opens":1170,"closes":1320},{"day":6,"opens":1170,"closes":1320}],"hours_source":"https://www.martinique.org/fr/bars-restaurants/restaurants/kay-ali","hours_updated_at":"2026-10-03T01:31:39.824059+00:00"},{"id":37,"name":"La Voile Blanche","type":"restaurant","lat":14.4810592,"lng":-61.023033,"location":"Le Diamant","description":"A cosy seafront restaurant in the town centre of Le Diamant with a varied menu of mixed and international cooking, many cocktails, and sun loungers by the sea. On Friday evenings there is a live concert of Caribbean and international music.","description_fr":"Un restaurant cosy en bord de mer dans le bourg du Diamant, avec une carte variée de cuisine métissée et internationale, de nombreux cocktails et des transats face à la mer. Le vendredi soir, un concert live de musiques caribéennes et internationales est proposé.","tags":["Beachfront"],"sources":[{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/la-voile-blanche","title":"Comité Martiniquais du Tourisme","fields":["Name","Town","Category","Description","Map point","Address","Telephone","Social media","Price range","Type","Payment","Languages spoken","Services","Opening hours"],"checkedAt":"2026-10-02"}],"access":"unknown","published":true,"details":{"from":{"kind":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/la-voile-blanche","checkedAt":"2026-10-02"},"phone":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/la-voile-blanche","checkedAt":"2026-10-02"},"address":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/la-voile-blanche","checkedAt":"2026-10-02"},"payment":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/la-voile-blanche","checkedAt":"2026-10-02"},"facebook":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/la-voile-blanche","checkedAt":"202