ux sur une pierre chaude, et propose aussi de grandes salades, des tartines et des pizzas.","tags":["International"],"sources":[{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/lannexe","title":"Comité Martiniquais du Tourisme","fields":["Name","Town","Category","Description","Map point","Address","Telephone","Social media","Price range","Type","Payment","Languages spoken","Services","Opening hours"],"checkedAt":"2026-10-02"}],"access":"unknown","published":true,"details":{"from":{"kind":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/lannexe","checkedAt":"2026-10-02"},"phone":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/lannexe","checkedAt":"2026-10-02"},"address":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/lannexe","checkedAt":"2026-10-02"},"payment":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/lannexe","checkedAt":"2026-10-02"},"facebook":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/lannexe","checkedAt":"2026-10-02"},"services":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/lannexe","checkedAt":"2026-10-02"},"languages":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/lannexe","checkedAt":"2026-10-02"},"priceRange":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/lannexe","checkedAt":"2026-10-02"}},"kind":["Cuisine du Monde"],"phone":"+596 596 38 84 77","address":"Rue du Chacha, le village créole, 97229 Les Trois-Ilets","payment":["Cartes bancaires","Espèces","Tickets restaurant"],"facebook":"https://www.facebook.com/LAnnexe.restaurant1","services":["Point wifi"],"languages":["Anglais","Espagnol","Français"],"priceRange":"12 €"},"opening_periods":[{"day":0,"opens":720,"closes":900},{"day":0,"opens":1140,"closes":1440},{"day":1,"opens":720,"closes":900},{"day":1,"opens":1140,"closes":1440},{"day":2,"opens":720,"closes":900},{"day":2,"opens":1140,"closes":1440},{"day":3,"opens":720,"clo