yment","Languages spoken","Services","Opening hours"],"checkedAt":"2026-10-02"}],"access":"unknown","published":true,"details":{"from":{"kind":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/le-beach-grill","checkedAt":"2026-10-02"},"phone":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/le-beach-grill","checkedAt":"2026-10-02"},"address":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/le-beach-grill","checkedAt":"2026-10-02"},"payment":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/le-beach-grill","checkedAt":"2026-10-02"},"website":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/le-beach-grill","checkedAt":"2026-10-02"},"facebook":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/le-beach-grill","checkedAt":"2026-10-02"},"services":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/le-beach-grill","checkedAt":"2026-10-02"},"languages":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/le-beach-grill","checkedAt":"2026-10-02"},"priceRange":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/le-beach-grill","checkedAt":"2026-10-02"}},"kind":["Restaurant de plage"],"phone":"+596 596 78 34 02","address":"2 Allee du Debarcadere, 97221 Le Carbet","payment":["Cartes bancaires","Chèques bancaires et postaux","Paypal","Tickets restaurant"],"website":"https://fr-fr.facebook.com/resto.beachgrill","facebook":"https://www.facebook.com/resto.beachgrill","services":["Point wifi"],"languages":["Anglais","Espagnol","Français"],"priceRange":"13–35 €"},"opening_periods":[{"day":0,"opens":720,"closes":870},{"day":2,"opens":690,"closes":840},{"day":3,"opens":690,"closes":840},{"day":4,"opens":690,"closes":840},{"day":4,"opens":1140,"closes":1260},{"day":5,"opens":690,"closes":840},{"day":5,"opens":1140,"closes":1320},{"day":6,"opens":690,"closes":840},{"day":6,"opens":1140,"closes":1320}],"hours_source":"https://www.martinique.org/fr/bars-restaurants/restaurants/le-beach-grill","hours_updated_at":"2026-10-03T01:31:40.965213+00:00"},{"id":41,"name":"Le Central","type":"restaurant","lat":14.609371,"lng":-61.07256,"location":"Fort-de-France","description":"A restaurant on the second floor of the Le Rond Point shopping centre serving homemade local dishes such as tinain with salt cod, sea bream, colombo and yams. It also has a grill bar, with meat and fish cooked to order, and a salad bar with a wide choice of fresh produce.","description_fr":"Au deuxième étage du centre commercial Le Rond Point, un restaurant de cuisine locale entièrement maison : tinain à la morue, dorade, colombo, ignames. Il compte aussi un comptoir de grillades (viandes et poissons à la minute) et un comptoir de salades garni de produits frais.","tags":["Creole"],"sources":[{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/le-central","title":"Comité Martiniquais du Tourisme","fields":["Name","Town","Category","Description","Map point","Address","Telephone","Price range","Type","Payment","Languages spoken","Services","Opening hours"],"checkedAt":"2026-10-02"}],"access":"unknown","published":true,"details":{"from":{"kind":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/le-central","checkedAt":"2026-10-02"},"phone":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/le-central","checkedAt":"2026-10-02"},"address":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/le-central","checkedAt":"2026-10-02"},"payment":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/le-central","checkedAt":"2026-10-02"},"services":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/le-central","checkedAt":"2026-10-02"},"languages":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/le-central","checkedAt":"2026-10-02"},"priceRange":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/le-central","checkedAt":"2026-10-02"}},"kind":["Cuisine traditionnelle"],"phone":"+596 696 03 06 17","address":"Centre Commercial Le Rond Poind, 97200 Fort-De-France","payment":["Cartes bancaires","Tickets restaurant"],"services":["Point wifi"],"languages":["Anglais","Français"],"priceRange":"9–30 €"},"opening_periods":[{"day":1,"opens":690,"closes":1020},{"day":2,"opens":690,"closes":1020},{"day":3,"opens":690,"closes":1020},{"day":4,"opens":690,"closes":1020},{"day":5,"opens":690,"closes":1020},{"day":6,"opens":690,"closes":1020}],"hours_source":"https://www.martinique.org/fr/bars-restaurants/restaurants/le-central","hours_updated_at":"2026-10-03T01:31:41.241213+00:00"},{"id":42,"name":"Le Cloud - Rooftop Bar","type":"restaurant","lat":14.60080808,"lng":-61.0451094,"location":"Fort-de-France","description":"A rooftop cocktail bar with a panoramic view over Fort-de-France. Beyond drinks, it hosts afterwork gatherings, electronic music nights and other events in an intimate, offbeat setting.","description_fr":"Un bar à cocktails en rooftop offrant une vue panoramique sur Fort-de-France. Au-delà des boissons, il accueille afterworks, soirées électro et autres événements, dans un cadre intime et atypique.","tags":["Bar","Nightlife"],"sources":[{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/le-cloud-rooftop-bar","title":"Comité Martiniquais du Tourisme","fields":["Name","Town","Category","Description","Map point","Telephone","Address","Website","Opening hours","Price range","Type","Payment"],"checkedAt":"2026-10-02"}],"access":"unknown","published":true,"details":{"from":{"kind":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/le-cloud-rooftop-bar","checkedAt":"2026-10-02"},"phone":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/le-cloud-rooftop-bar","checkedAt":"2026-10-02"},"address":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/le-cloud-rooftop-bar","checkedAt":"2026-10-02"},"payment":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/le-cloud-rooftop-bar","checkedAt":"2026-10-02"},"website":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/le-cloud-rooftop-bar","checkedAt":"2026-10-02"},"hoursText":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/le-cloud-rooftop-bar","checkedAt":"2026-10-02"},"priceRange":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/le-cloud-rooftop-bar","checkedAt":"2026-10-02"}},"kind":["Bar"],"phone":"+596 596 67 33 76","address":"97200 Fort-De-France","payment":["Cartes bancaires","Espèces"],"website":"https://www.cloudrooftopbar.com/","hoursText":"Lundi : 17h00 - 00h00\nMardi : 17h00 - 00h00\nMercredi : 17h00 - 00h00\nJeudi : 17h00 - 00h00\nVendredi : 17h00 - 01h00\nSamedi : 19h00 - 01h00\nDimanche : 19h00 - 00h00","priceRange":"12–25 €"}},{"id":43,"name":"Le Dome","type":"restaurant","lat":14.618094,"lng":-61.040661,"location":"Fort-de-France","description":"A rooftop restaurant in the Karibea Valmenière hotel with panoramic views over the city and the Caribbean Sea. The refined, mixed cooking uses fresh seasonal ingredients with strong French and Creole influences, in an elegant setting that suits business meals and special occasions.","description_fr":"Le restaurant en rooftop de l’hôtel Karibea Valmenière, qui domine la ville et la mer des Caraïbes. La carte métissée et soignée travaille des ingrédients frais de saison où se mêlent influences françaises et créoles ; l’endroit, élégant, convient aux repas d’affaires comme aux grandes occasions.","tags":["Fine Dining"],"sources":[{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/le-dome","title":"Comité Martiniquais du Tourisme","fields":["Name","Town","Category","Description","Map point","Address","Telephone","Website","Social media","Price range","Type","Payment","Languages spoken","Services","Accessibility"],"checkedAt":"2026-10-02"}],"access":"unknown","published":true,"details":{"from":{"kind":{"url":"https://www.mart