":[{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/le-rameau-de-champfleury","title":"Comité Martiniquais du Tourisme","fields":["Name","Town","Category","Description","Map point","Address","Telephone","Social media","Type","Payment","Languages spoken","Services","Opening hours"],"checkedAt":"2026-10-02"}],"access":"unknown","published":true,"details":{"from":{"kind":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/le-rameau-de-champfleury","checkedAt":"2026-10-02"},"phone":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/le-rameau-de-champfleury","checkedAt":"2026-10-02"},"address":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/le-rameau-de-champfleury","checkedAt":"2026-10-02"},"payment":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/le-rameau-de-champfleury","checkedAt":"2026-10-02"},"facebook":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/le-rameau-de-champfleury","checkedAt":"2026-10-02"},"services":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/le-rameau-de-champfleury","checkedAt":"2026-10-02"},"instagram":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/le-rameau-de-champfleury","checkedAt":"2026-10-02"},"languages":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/le-rameau-de-champfleury","checkedAt":"2026-10-02"}},"kind":["Cuisine traditionnelle"],"phone":"+596 596 74 03 63","address":"Cap Champfleury, 97290 Le Marin","payment":["Cartes bancaires","Chèques bancaires et postaux","Chèques vacances","Tickets restaurant"],"facebook":"https://www.facebook.com/ChezLouise972","services":["Point wifi"],"instagram":"https://instagram.com/chezlouise__","languages":["Anglais","Français"]},"opening_periods":[{"day":0,"opens":720,"closes":900},{"day":2,"opens":720,"closes":900},{"day":3,"opens":720,"closes":900},{"day":4,"opens":720,"closes":900},{"day":5,"opens":720,"closes":900},{"day":6,"opens":72