artiniquais du Tourisme","fields":["Name","Town","Category","Description","Map point","Address","Type"],"checkedAt":"2026-10-02"}],"access":"unknown","published":true,"details":{"from":{"kind":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/le-sunnys-beach","checkedAt":"2026-10-02"},"address":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/le-sunnys-beach","checkedAt":"2026-10-02"}},"kind":["Cuisine traditionnelle"],"address":"Anse Figuier, 97211 Riviere-Pilote"}},{"id":57,"name":"L''imperatrice","type":"restaurant","lat":14.6035427,"lng":-61.068612,"location":"Fort-de-France","description":"Le Joséphine is the restaurant on the first floor of Hôtel L''Impératrice in central Fort-de-France, serving flavourful, refined Creole cooking in an elegant room. A Creole buffet is served on Thursday lunchtimes, and booking is advised.","description_fr":"Le Joséphine est le restaurant du premier étage de l’hôtel L’Impératrice, au centre de Fort-de-France, avec une cuisine créole savoureuse et raffinée dans un cadre élégant. Un buffet créole est proposé le jeudi midi, sur réservation conseillée.","tags":["Creole"],"sources":[{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/limperatrice","title":"Comité Martiniquais du Tourisme","fields":["Name","Town","Category","Description","Map point","Address","Telephone","Website","Price range","Type","Payment","Languages spoken","Services","Opening hours"],"checkedAt":"2026-10-02"}],"access":"unknown","published":true,"details":{"from":{"kind":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/limperatrice","checkedAt":"2026-10-02"},"phone":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/limperatrice","checkedAt":"2026-10-02"},"address":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/limperatrice","checkedAt":"2026-10-02"},"payment":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/limperatrice","checkedAt":"2026-10-02"},"website":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/limperatrice","checkedAt":"2026-10-02"},"services":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/limperatrice","checkedAt":"2026-10-02"},"languages":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/limperatrice","checkedAt":"2026-10-02"},"priceRange":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/limperatrice","checkedAt":"2026-10-02"}},"kind":["Cuisine traditionnelle"],"phone":"+596 596 63 06 82","address":"15, rue de la Liberté, 97200 Fort-De-France","payment":["Cartes bancaires","Chèques bancaires et postaux","Tickets restaurant"],"website":"https://www.limperatricehotel.fr/","services":["Point wifi"],"languages":["Anglais","Français"],"priceRange":"12–40 €"},"opening_periods":[{"day":1,"opens":720,"closes":870},{"day":1,"opens":1155,"closes":1290},{"day":2,"opens":720,"closes":870},{"day":2,"opens":1155,"closes":1290},{"day":3,"opens":720,"closes":870},{"day":3,"opens":1155,"closes":1290},{"day":4,"opens":720,"closes":870},{"day":4,"opens":1155,"closes":1290},{"day":5,"opens":720,"closes":870},{"day":5,"opens":1155,"closes":1290},{"day":6,"opens":720,"closes":870},{"day":6,"opens":1155,"closes":1290}],"hours_source":"https://www.martinique.org/fr/bars-restaurants/restaurants/limperatrice","hours_updated_at":"2026-10-03T01:31:44.875961+00:00"},{"id":58,"name":"L''imprevu","type":"restaurant","lat":14.705165,"lng":-61.183277,"location":"Le Carbet","description":"A Creole restaurant in Le Carbet with a dining room open to the Caribbean Sea. It has been serving for more than 45 years, passing Creole cooking from father to son, and prepares authentic Martinican meals from fresh local produce.","description_fr":"Un restaurant créole au Carbet dont la salle s’ouvre sur la mer des Caraïbes. Fondé il y a plus de 45 ans, il perpétue une cuisine créole transmise de père en fils, avec des repas authentiquement martiniquais à base de produits frais du terroir.","tags":["Beachfront"],"sources":[{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/limprevu","title":"Comité Martiniquais du Tourisme","fields":["Name","Town","Category","Description","Map point","Address","Telephone","Social media","Price range","Type","Payment","Languages spoken","Services","Accessibility","Opening hours"],"checkedAt":"2026-10-02"}],"access":"unknown","published":true,"details":{"from":{"kind":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/limprevu","checkedAt":"2026-10-02"},"phone":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/limprevu","checkedAt":"2026-10-02"},"address":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/limprevu","checkedAt":"2026-10-02"},"payment":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/limprevu","checkedAt":"2026-10-02"},"facebook":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/limprevu","checkedAt":"2026-10-02"},"services":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/limprevu","checkedAt":"2026-10-02"},"instagram":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/limprevu","checkedAt":"2026-10-02"},"languages":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/limprevu","checkedAt":"2026-10-02"},"priceRange":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/limprevu","checkedAt":"2026-10-02"},"accessibility":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/limprevu","checkedAt":"2026-10-02"}},"kind":["Restaurant de plage"],"phone":"+596 596 78 01 02","address":"Quartier Grande Anse, 97221 Le Carbet","payment":["Cartes bancaires","Chèques bancaires et postaux","Chèques vacances","Tickets restaurant"],"facebook":"https://www.facebook.com/limprevu.carbet","services":["Point wifi"],"instagram":"https://instagram.com/restaurant_limprevu_le_carbet","languages":["Anglais","Français"],"priceRange":"6,50–40 €","accessibility":"Déficience auditive, Déficience mentale, Déficience moteur, Déficience visuelle"},"opening_periods":[{"day":0,"opens":690,"closes":900},{"day":1,"opens":690,"closes":960},{"day":2,"opens":690,"closes":1380},{"day":3,"opens":690,"closes":1380},{"day":4,"opens":690,"closes":1380},{"day":5,"opens":690,"closes":1380},{"day":6,"opens":690,"closes":1380}],"hours_source":"https://www.martinique.org/fr/bars-restaurants/restaurants/limprevu","hours_updated_at":"2026-10-03T01:31:45.147718+00:00"},{"id":59,"name":"Miza","type":"restaurant","lat":14.61398219,"lng":-61.0393793,"location":"Fort-de-France","description":"A discreet restaurant in the middle of a commercial zone in Fort-de-France, hiding an elegant, hushed dining room. There is no fixed menu: the chef surprises guests with each dish, and the name comes from Mizaru, the monkey who covers his eyes.","description_fr":"Un restaurant discret au cœur d’une zone commerciale de Fort-de-France, qui cache une salle élégante et feutrée. Il n’y a pas de menu préétabli : le chef surprend les convives à chaque plat, et le nom vient de Mizaru, le singe qui se couvre les yeux.","tags":["Fine Dining"],"sources":[{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/miza","title":"Comité Martiniquais du Tourisme","fields":["Name","Town","Category","Description","Map point","Address","Telephone","Social media","Price range","Type","Payment","Languages spoken","Services"],"checkedAt":"2026-10-02"}],"access":"unknown","published":true,"details":{"from":{"kind":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/miza","checkedAt":"2026-10-02"},"phone":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/miza","checkedAt":"2026-10-02"},"address":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/miza","checkedAt":"2026-10-02"},"payment":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/miza","checkedAt":"2026-10-02"},"services":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/miza","checkedAt":"2026-10-02"},"instagram":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/miza","checkedAt":"2026-10-02"},"languages":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/miza","checkedAt":"2026-10-02"},"priceRange":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/miza","checkedAt":"2026-10-02"}},"kind":["Restaurant gastronomique - cuisine raffinée"],"phone":"+596 596 09 01 62","address":"BAT F4 ZAC de Riviere Roche, 97200 Fort-De-France","payment":["Cartes bancaires","Espèces"],"services":["Point wifi"],"instagram":"https://instagram.com/miza_mq","languages":["Anglais","Français"],"priceRange":"45–100 €"}},{"id":60,"name":"North Beach","type":"restaurant","lat":14.7844639,"lng":-60.9914932,"location":"Sainte-Marie","description":"A restaurant on the north Atlantic coast of Sainte-Marie with a sea view opposite the striking tombolo. The menu is original, with surf-and-turf dishes and a tiramisu made like a Mont-Blanc, and the self-taught chef cooks simple, mixed-influence food.","description_fr":"Un restaurant de la côte nord-atlantique, à Sainte-Marie, avec vue sur la mer face au tombolo. La carte est originale, avec des plats terre et mer et un tiramisu façon Mont-Blanc, et la cheffe, autodidacte, signe une cuisine métissée simple et gourmande.","tags":["Creole"],"sources":[{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/north-beach","title":"Comité Martiniquais du Tourisme","fields":["Name","Town","Category","Description","Map point","Address","Telephone","Social media","Price range","Type","Payment","Opening hours"],"checkedAt":"2026-10-02"}],"access":"unknown","published":true,"details":{"from":{"kind":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/north-beach","checkedAt":"2026-10-02"},"phone":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/north-beach","checkedAt":"2026-10-02"},"address":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/north-beach","checkedAt":"2026-10-02"},"payment":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/north-beach","checkedAt":"2026-10-02"},"instagram":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/north-beach","checkedAt":"2026-10-02"},"priceRange":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/north-beach","checkedAt":"2026-10-02"}},"kind":["Cuisine traditionnelle"],"phone":"+596 696 70 80 89","address":"62 Boulevard Desir Jox, 97230 Sainte-Marie","payment":["Cartes bancaires","Espèces"],"instagram":"https://instagram.com/northbeach.tombolo","priceRange":"30–40 €"},"opening_periods":[{"day":0,"opens":720,"closes":960},{"day":1,"opens":720,"closes":960},{"day":2,"opens":720,"closes":960},{"day":3,"opens":720,"closes":960},{"day":4,"opens":720,"closes":1320},{"day":5,"opens":720,"closes":1380},{"day":6,"opens":720,"closes":1380}],"hours_source":"https://www.martinique.org/fr/bars-restaurants/restaurants/north-beach","hours_updated_at":"2026-10-03T01:31:45.568254+00:00"},{"id":61,"name":"Obuzz","type":"restaurant","lat":14.5975451,"lng":-60.9559752,"location":"Ducos","description":"A restaurant-bar in Ducos that serves lunch to eat in or take away and a semi-gastronomic menu in the evening. The dishes are fully homemade from fresh local produce, in an intimate, warm setting, with a bar for a relaxed drink.","description_fr":"Un restaurant-bar à Ducos : le midi, une cuisine à déguster sur place ou à emporter ; le soir, une carte semi-gastronomique. Les plats sont entièrement faits maison avec des produits frais du terroir, dans un cadre intimiste et chaleureux, avec un bar pour se détendre autour d’un verre.","tags":["Creole"],"sources":[{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/obuzz","title":"Comité Martiniquais du Tourisme","fields":["Name","Town","Category","Description","Map point","Address","Social media","Type","Payment","Opening hours"],"checkedAt":"2026-10-02"}],"access":"unknown","published":true,"details":{"from":{"kind":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/obuzz","checkedAt":"2026-10-02"},"address":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/obuzz","checkedAt":"2026-10-02"},"payment":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/obuzz","checkedAt":"2026-10-02"},"facebook":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/obuzz","checkedAt":"2026-10-02"},"instagram":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/obuzz","checkedAt":"2026-10-02"}},"kind":["Cuisine traditionnelle"],"address":"Qua Fond D Or, 97224 Ducos","payment":["Cartes bancaires","Espèces"],"facebook":"https://www.facebook.com/obuzz.martinique","instagram":"https://instagram.com/obuzz_restaurant_bar"},"opening_periods":[{"day":2,"opens":690,"closes":930},{"day":2,"opens":1080,"closes":1320},{"day":3,"opens":690,"closes":930},{"day":3,"opens":1080,"closes":1320},{"day":4,"opens":690,"closes":930},{"day":4,"opens":1080,"closes":1320},{"day":5,"opens":690,"closes":930},{"day":5,"opens":1080,"closes":1380},{"day":6,"opens":1080,"closes":1380}],"hours_source":"https://www.martinique.org/fr/bars-restaurants/restaurants/obuzz","hours_updated_at":"2026-10-03T01:31:46.006188+00:00"},{"id":62,"name":"People Beach","type":"restaurant","lat":14.4274755,"lng":-60.885199,"location":"Sainte-Anne","description":"A seafront restaurant in Sainte-Anne with a clear view of the Caribbean Sea, a chic but relaxed mood, sun loungers, pools and live evenings in a Caribbean-style hacienda. The varied menu includes specialities such as a Louisiana-style Cajun boil, and the venue can be hired privately for up to 300 seated guests.","description_fr":"Un restaurant en bord de mer à Sainte-Anne, face à la mer des Caraïbes, dans une ambiance chic et décontractée, avec bains de soleil, transats, piscines et soirées live dans une hacienda de style caribéen. La carte variée inclut des spécialités comme le Cajun boil de Louisiane, et le lieu peut être privatisé jusqu’à 300 personnes assises.","tags":["Beachfront"],"sources":[{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/people-beach","title":"Comité Martiniquais du Tourisme","fields":["Name","Town","Category","Description","Map point","Address","Telephone","Price range","Type","Payment","Languages spoken","Opening hours"],"checkedAt":"2026-10-02"}],"access":"unknown","published":true,"details":{"from":{"kind":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/people-beach","checkedAt":"2026-10-02"},"phone":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/people-beach","checkedAt":"2026-10-02"},"address":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/people-beach","checkedAt":"2026-10-02"},"payment":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/people-beach","checkedAt":"2026-10-02"},"languages":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/people-beach","checkedAt":"2026-10-02"},"priceRange":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/people-beach","checkedAt":"2026-10-02"}},"kind":["Restaurant de plage"],"phone":"+596 596 71 58 80","address":"Domaine de l''Anse Caritan, 97227 Sainte-Anne","payment":["Cartes bancaires","Espèces","Tickets restaurant"],"languages":["Anglais","Français"],"priceRange":"11–31 €"},"opening_periods":[{"day":0,"opens":630,"closes":1200},{"day":1,"opens":630,"closes":1200},{"day":2,"opens":630,"closes":1200},{"day":3,"opens":630,"closes":1200},{"day":4,"opens":630,"closes":1200},{"day":5,"opens":630,"closes":1380},{"day":6,"opens":630,"closes":1320}],"hours_source":"https://www.martinique.org/fr/bars-restaurants/restaurants/people-beach","hours_updated_at":"2026-10-03T01:31:46.30191+00:00"},{"id":63,"name":"Plein Soleil","type":"restaurant","lat":14.644357,"lng":-60.901746,"location":"Le François","description":"The gastronomic restaurant of Hôtel Plein Soleil in Le François, laid out like a table d''hôtes and open to outside guests by reservation. A bright, stylish room overlooks the bay, and the chef cooks creative, fragrant food with a focus on fish and seafood, with new suggestions each month.","description_fr":"Le restaurant gastronomique de l’hôtel Plein Soleil, au François, conçu comme une table d’hôtes et ouvert à la clientèle extérieure sur réservation. Une salle lumineuse et chic donne sur la baie, et le chef propose une cuisine créative et parfumée, centrée sur le poisson et les fruits de mer, avec de nouvelles suggestions chaque mois.","tags":["Fine Dining"],"sources":[{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/plein-soleil","title":"Comité Martiniquais du Tourisme","fields":["Name","Town","Category","Description","Map point","Address","Telephone","Website","Social media","Price range","Type","Payment","Languages spoken","Services"],"checkedAt":"2026-10-02"}],"access":"unknown","published":true,"details":{"from":{"kind":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/plein-soleil","checkedAt":"2026-10-02"},"phone":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/plein-soleil","checkedAt":"2026-10-02"},"address":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/plein-soleil","checkedAt":"2026-10-02"},"payment":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/plein-soleil","checkedAt":"2026-10-02"},"website":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/plein-soleil","checkedAt":"2026-10-02"},"facebook":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/plein-soleil","checkedAt":"2026-10-02"},"services":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/plein-soleil","checkedAt":"2026-10-02"},"languages":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/plein-soleil","checkedAt":"2026-10-02"},"priceRange":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/plein-soleil","checkedAt":"2026-10-02"}},"kind":["Restaurant gastronomique - cuisine raffinée"],"phone":"+596 596 38 07 77","address":"Pointe Thalemont, 97240 Le François","payment":["Cartes bancaires","Chèques vacances","Espèces","Virement bancaire"],"website":"https://www.hotelpleinsoleil.fr/","facebook":"https://www.facebook.com/pages/H%C3%B4tel-Plein-Soleil-Martinique/147610748608943","services":["Point wifi"],"languages":["Anglais","Français"],"priceRange":"60 €"}},{"id":64,"name":"Quinoa Beach","type":"restaurant","lat":14.6421449,"lng":-61.1388076,"location":"Case-Pilote","description":"Traditional-cuisine restaurant on Rue de la Plage in Case-Pilote, on Martinique’s Caribbean coast.","description_fr":"Restaurant de cuisine traditionnelle situé rue de la Plage, à Case-Pilote, sur la côte caraïbe de la Martinique.","tags":["Creole"],"sources":[{"url":"https://www.martinique.org/fr/quinoa-beach","title":"Comité Martiniquais du Tourisme","fields":["Name","Town","Category","Description","Map point","Address","Type"],"checkedAt":"2026-10-02"}],"access":"unknown","published":true,"details":{"from":{"kind":{"url":"https://www.martinique.org/fr/quinoa-beach","checkedAt":"2026-10-02"},"address":{"url":"https://www.martinique.org/fr/quinoa-beach","checkedAt":"2026-10-02"}},"kind":["Cuisine traditionnelle"],"address":"Rue de la Plage, Case-Pilote"}},{"id":65,"name":"Refuge De L''aileron","type":"restaurant","lat":14.80589388,"lng":-61.1508691,"location":"Le Morne-Rouge","description":"A restaurant at the first shelter on Montagne Pelée, in a peaceful setting that suits a meal after a hike. It serves generous Creole and French dishes such as Creole boudin, accras and smoked chicken, plus grills.","description_fr":"Un restaurant au premier abri de la montagne Pelée, dans un cadre paisible, idéal pour une pause après une randonnée. La cuisine est généreuse, d’inspiration créole et française : boudin créole, acras, poulet boucané et grillades.","tags":["Creole"],"sources":[{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/refuge-de-laileron","title":"Comité Martiniquais du Tourisme","fields":["Name","Town","Category","Description","Map point","Address","Telephone","Website","Social media","Price range","Type","Payment","Languages spoken","Services","Opening hours"],"checkedAt":"2026-10-02"}],"access":"unknown","published":true,"details":{"from":{"kind":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/refuge-de-laileron","checkedAt":"2026-10-02"},"phone":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/refuge-de-laileron","checkedAt":"2026-10-02"},"address":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/refuge-de-laileron","checkedAt":"2026-10-02"},"payment":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/refuge-de-laileron","checkedAt":"2026-10-02"},"website":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/refuge-de-laileron","checkedAt":"2026-10-02"},"facebook":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/refuge-de-laileron","checkedAt":"2026-10-02"},"services":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/refuge-de-laileron","checkedAt":"2026-10-02"},"instagram":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/refuge-de-laileron","checkedAt":"2026-10-02"},"languages":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/refuge-de-laileron","checkedAt":"2026-10-02"},"priceRange":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/refuge-de-laileron","checkedAt":"2026-10-02"}},"kind":["Cuisine traditionnelle"],"phone":"+596 596 52 38 08","address":"1er Abri Montagne Pelée, Morne Rouge (le), 97260 Le Morne-Rouge","payment":["Cartes bancaires","Chèques bancaires et postaux","Chèques vacances","Espèces","Tickets restaurant","V