026-10-02"}],"access":"unknown","published":true,"details":{"from":{"kind":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/restaurant-bodlanme","checkedAt":"2026-10-02"},"phone":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/restaurant-bodlanme","checkedAt":"2026-10-02"},"address":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/restaurant-bodlanme","checkedAt":"2026-10-02"},"payment":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/restaurant-bodlanme","checkedAt":"2026-10-02"},"website":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/restaurant-bodlanme","checkedAt":"2026-10-02"},"facebook":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/restaurant-bodlanme","checkedAt":"2026-10-02"},"services":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/restaurant-bodlanme","checkedAt":"2026-10-02"},"instagram":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/restaurant-bodlanme","checkedAt":"2026-10-02"},"languages":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/restaurant-bodlanme","checkedAt":"2026-10-02"},"priceRange":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/restaurant-bodlanme","checkedAt":"2026-10-02"},"accessibility":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/restaurant-bodlanme","checkedAt":"2026-10-02"}},"kind":["Restaurant de plage"],"phone":"+596 596 66 01 39","address":"Bambou Resort, 97229 Les Trois-Ilets","payment":["Cartes bancaires","Chèques vacances","Espèces","Tickets restaurant"],"website":"https://www.bambouresort.com/nos-restaurants/restaurant-bodlanme","facebook":"https://www.facebook.com/restaurantbodlanme","services":["Point wifi"],"instagram":"https://instagram.com/bodlanme_restaurant","languages":["Anglais","Français"],"priceRange":"10–60 €","accessibility":"Déficience auditive, Déficience mentale, Déficience moteur, Déficience visuel