estaurants/restaurant-chez-milo","checkedAt":"2026-10-02"},"website":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/restaurant-chez-milo","checkedAt":"2026-10-02"},"services":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/restaurant-chez-milo","checkedAt":"2026-10-02"},"languages":{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/restaurant-chez-milo","checkedAt":"2026-10-02"}},"kind":["Cuisine traditionnelle"],"phone":"+596 596 54 65 70","address":"Presqu''Ile, 97240 Le François","payment":["Cartes bancaires","Espèces","Tickets restaurant"],"website":"https://www.chezmilo.com/","services":["Point wifi"],"languages":["Anglais","Français"]},"opening_periods":[{"day":1,"opens":720,"closes":960},{"day":2,"opens":720,"closes":960},{"day":3,"opens":720,"closes":960},{"day":4,"opens":720,"closes":960},{"day":5,"opens":720,"closes":960},{"day":6,"opens":630,"closes":960}],"hours_source":"https://www.martinique.org/fr/bars-restaurants/restaurants/restaurant-chez-milo","hours_updated_at":"2026-10-03T01:31:47.514916+00:00"},{"id":68,"name":"Restaurant Les Arômes","type":"restaurant","lat":14.70991,"lng":-61.182892,"location":"Le Carbet","description":"A friendly family-style restaurant in Le Carbet where the meal feels like lunch at an aunt''s house. Fans and misters keep the room cool, and the food is based on fresh local produce.","description_fr":"Un restaurant convivial du Carbet où l’on a l’impression de déjeuner chez une tante. Ventilateurs et brumisateurs rafraîchissent la salle, et la cuisine repose sur des produits frais et locaux.","tags":["Creole"],"sources":[{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/restaurant-les-aromes","title":"Comité Martiniquais du Tourisme","fields":["Name","Town","Category","Description","Map point","Address","Telephone","Website","Social media","Price range","Type","Payment","Languages spoken","Services","Accessibility","Opening hours"],"checkedAt":"2026-10-0