om":{"phone":{"url":"https://www.martinique.org/fr/que-faire/bien-etre/la-villa-victoria","checkedAt":"2026-10-02"},"address":{"url":"https://www.martinique.org/fr/que-faire/bien-etre/la-villa-victoria","checkedAt":"2026-10-02"},"payment":{"url":"https://www.martinique.org/fr/que-faire/bien-etre/la-villa-victoria","checkedAt":"2026-10-02"},"facebook":{"url":"https://www.martinique.org/fr/que-faire/bien-etre/la-villa-victoria","checkedAt":"2026-10-02"},"instagram":{"url":"https://www.martinique.org/fr/que-faire/bien-etre/la-villa-victoria","checkedAt":"2026-10-02"},"languages":{"url":"https://www.martinique.org/fr/que-faire/bien-etre/la-villa-victoria","checkedAt":"2026-10-02"}},"phone":"+596 696 82 12 10","address":"99 Route de Ravine Vilaine, 97200 Fort-De-France","payment":["Chèques bancaires et postaux","Espèces","Virement bancaire"],"facebook":"https://www.facebook.com/villavictoriamartinique","instagram":"https://instagram.com/villavictoriamartinique","languages":["Français"]}},{"id":81,"name":"Natur''o Péyi","type":"activity","lat":14.7135931,"lng":-61.173485,"location":"Le Carbet","description":"A wellness spot in nature near Le Carbet, with the sound of water and energy-focused massage. It offers Ayurvedic massages, including abhyanga, a toning, enveloping full-body massage that works from scalp to toes.","description_fr":"Un lieu de bien-être en pleine nature près du Carbet, bercé par le bruit de l’eau, qui propose des massages énergétiques et ayurvédiques, dont l’abhyanga, un massage tonique et enveloppant qui va du cuir chevelu aux orteils.","tags":["Wellness"],"sources":[{"url":"https://www.martinique.org/fr/que-faire/bien-etre/naturo-peyi","title":"Comité Martiniquais du Tourisme","fields":["Name","Town","Category","Description","Map point","Address","Telephone","Social media","Price range","Payment","Languages spoken"],"checkedAt":"2026-10-02"}],"access":"unknown","published":true,"details":{"from":{"phone":{"url":"https://www.martinique.org/fr/que-faire/bien-etre/naturo-peyi","checkedAt":"2026-10-02"},"address":{"url":"https://www.martinique.org/fr/que-faire/bien-etre/naturo-peyi","checkedAt":"2026-10-02"},"payment":{"url":"https://www.martinique.org/fr/que-faire/bien-etre/naturo-peyi","checkedAt":"2026-10-02"},"facebook":{"url":"https://www.martinique.org/fr/que-faire/bien-etre/naturo-peyi","checkedAt":"2026-10-02"},"instagram":{"url":"https://www.martinique.org/fr/que-faire/bien-etre/naturo-peyi","checkedAt":"2026-10-02"},"languages":{"url":"https://www.martinique.org/fr/que-faire/bien-etre/naturo-peyi","checkedAt":"2026-10-02"},"priceRange":{"url":"https://www.martinique.org/fr/que-faire/bien-etre/naturo-peyi","checkedAt":"2026-10-02"}},"phone":"+596 696 73 77 74","address":"Route des Pitons, 97221 Le Carbet","payment":["Cartes bancaires","Espèces","Paypal","Virement bancaire"],"facebook":"https://www.facebook.com/profile.php","instagram":"https://instagram.com/naturopeyi","languages":["Français"],"priceRange":"60–90 €"}},{"id":82,"name":"Revi","type":"activity","lat":14.72713755,"lng":-61.180016,"location":"Le Carbet","description":"A half-day excursion concept that combines discovering the island with wellbeing and personal development: sea and river, tropical fruit, natural spas and outdoor coaching sessions such as yoga and meditation. The 5-hour session is open to everyone, including children.","description_fr":"Un concept d’excursion d’une demi-journée qui mêle balade sur l’île, bien-être et développement personnel : mer, rivière, fruits tropicaux, spas naturels, plus du coaching en plein air (yoga, méditation). La sortie dure cinq heures, tout public, enfants acceptés.","tags":["Guided Tour","Wellness"],"sources":[{"url":"https://www.martinique.org/fr/que-faire/bien-etre/revi","title":"Comité Martiniquais du Tourisme","fields":["Name","Town","Category","Description","Map point","Address","Telephone","Website","Social media","Payment","Languages spoken"],"checkedAt":"2026-10-02"}],"access":"unknown","published":true,"details":{"from":{"phone":{"url":"https://www.martinique.org/fr/que-faire/bien-etre/revi","checkedAt":"2026-10-02"},"address":{"url":"https://www.martinique.org/fr/que-faire/bien-etre/revi","checkedAt":"2026-10-02"},"payment":{"url":"https://www.martinique.org/fr/que-faire/bien-etre/revi","checkedAt":"2026-10-02"},"website":{"url":"https://www.martinique.org/fr/que-faire/bien-etre/revi","checkedAt":"2026-10-02"},"facebook":{"url":"https://www.martinique.org/fr/que-faire/bien-etre/revi","checkedAt":"2026-10-02"},"languages":{"url":"https://www.martinique.org/fr/que-faire/bien-etre/revi","checkedAt":"2026-10-02"}},"phone":"+596 696 93 79 80","address":"Chemin Varin De La Brunelière, Plateau Godinot, 97221 Le Carbet","payment":["Cartes bancaires","Chèques bancaires et postaux","Chèques vacances","Virement bancaire"],"website":"https://myreviholidays.com/","facebook":"https://www.facebook.com/HolidaysToReviveYourLife","languages":["Anglais","Espagnol","Français"]}},{"id":83,"name":"Spa Josephine","type":"activity","lat":14.53,"lng":-61.03,"location":"Les Trois-Îlets","description":"A spa inside the Carayou hotel in Les Trois-Îlets, with toning massages and relaxing scrubs facing the Caribbean Sea and the bay. The team looks after guests from head to toe in a warm, hushed atmosphere.","description_fr":"Un spa de l’hôtel Carayou, aux Trois-Îlets, avec vue sur la mer des Caraïbes et la baie : soins tonifiants, gommages relaxants et massages. L’équipe prend soin des clients de la tête aux pieds, dans une atmosphère chaleureuse et feutrée.","tags":["Wellness","Spa"],"sources":[{"url":"https://www.martinique.org/fr/que-faire/bien-etre/spa-josephine","title":"Comité Martiniquais du Tourisme","fields":["Name","Town","Category","Description","Map point","Address","Telephone","Website","Social media","Price range","Payment","Languages spoken","Opening hours"],"checkedAt":"2026-10-02"}],"access":"unknown","published":true,"details":{"from":{"phone":{"url":"https://w