milieu naturel. L’équipage partage ses connaissances sur les espèces et leurs habitats, dans le respect du milieu marin.","tags":["Diving"],"sources":[{"url":"https://www.martinique.org/fr/que-faire/sports-activites-nautiques/atao-plongee","title":"Comité Martiniquais du Tourisme","fields":["Name","Town","Category","Description","Map point","Address","Telephone","Website","Social media","Price range","Payment","Languages spoken","Opening hours"],"checkedAt":"2026-10-02"}],"access":"unknown","published":true,"details":{"from":{"phone":{"url":"https://www.martinique.org/fr/que-faire/sports-activites-nautiques/atao-plongee","checkedAt":"2026-10-02"},"address":{"url":"https://www.martinique.org/fr/que-faire/sports-activites-nautiques/atao-plongee","checkedAt":"2026-10-02"},"payment":{"url":"https://www.martinique.org/fr/que-faire/sports-activites-nautiques/atao-plongee","checkedAt":"2026-10-02"},"website":{"url":"https://www.martinique.org/fr/que-faire/sports-activites-nautiques/atao-plongee","checkedAt":"2026-10-02"},"facebook":{"url":"https://www.martinique.org/fr/que-faire/sports-activites-nautiques/atao-plongee","checkedAt":"2026-10-02"},"instagram":{"url":"https://www.martinique.org/fr/que-faire/sports-activites-nautiques/atao-plongee","checkedAt":"2026-10-02"},"languages":{"url":"https://www.martinique.org/fr/que-faire/sports-activites-nautiques/atao-plongee","checkedAt":"2026-10-02"},"priceRange":{"url":"https://www.martinique.org/fr/que-faire/sports-activites-nautiques/atao-plongee","checkedAt":"2026-10-02"}},"phone":"+596 696 32 47 96","address":"Ponton de Grande Anse d Arlet, 97217 Les Anses-D''Arlet","payment":["Cartes bancaires","Chèques vacances","Espèces","Paypal","Virement bancaire"],"website":"https://www.atao-plongee.fr/","facebook":"https://www.facebook.com/AtaoPlongee","instagram":"https://instagram.com/ataoplongee","languages":["Allemand","Anglais","Espagnol","Français"],"priceRange":"59–94 €"},"opening_periods":[{"day":0,"opens":510,"closes":1020},{