.martinique.org/fr/que-faire/sports-activites-nautiques/canopee-bleue","checkedAt":"2026-10-02"},"payment":{"url":"https://www.martinique.org/fr/que-faire/sports-activites-nautiques/canopee-bleue","checkedAt":"2026-10-02"},"website":{"url":"https://www.martinique.org/fr/que-faire/sports-activites-nautiques/canopee-bleue","checkedAt":"2026-10-02"},"languages":{"url":"https://www.martinique.org/fr/que-faire/sports-activites-nautiques/canopee-bleue","checkedAt":"2026-10-02"}},"phone":"+596 696 34 20 70","address":"Ponton Anse du bourg, 97217 Les Anses-D''Arlet","payment":["Cartes bancaires","Chèques bancaires et postaux","Espèces","Virement bancaire"],"website":"https://www.canopeebleue.com/","languages":["Anglais","Espagnol","Français"]}},{"id":213,"name":"Captain Didicô","type":"activity","lat":14.67935384,"lng":-60.9376022,"location":"Le Robert","description":"A team offering boat outings aboard DyNaMo for a day or a few hours, to share good moments on the water with family, friends or colleagues, for birthdays, weddings, exam successes or company seminars.","description_fr":"Une équipe qui propose des balades à bord de DyNaMo, pour une journée ou quelques heures, à partager en famille, entre amis ou entre collègues : anniversaire, mariage, réussite aux examens ou séminaire d’entreprise.","tags":["Boat Trip"],"sources":[{"url":"https://www.martinique.org/fr/que-faire/sports-activites-nautiques/captain-didico","title":"Comité Martiniquais du Tourisme","fields":["Name","Town","Category","Description","Map point","Address","Telephone","Website","Social media","Price range","Payment","Languages spoken","Opening hours"],"checkedAt":"2026-10-02"}],"access":"unknown","published":true,"details":{"from":{"phone":{"url":"https://www.martinique.org/fr/que-faire/sports-activites-nautiques/captain-didico","checkedAt":"2026-10-02"},"address":{"url":"https://www.martinique.org/fr/que-faire/sports-activites-nautiques/captain-didico","checkedAt":"2026-10-02"},"payment":{"url":"https