/sports-activites-nautiques/centrale-du-bateau","checkedAt":"2026-10-02"},"priceRange":{"url":"https://www.martinique.org/fr/que-faire/sports-activites-nautiques/centrale-du-bateau","checkedAt":"2026-10-02"}},"phone":"+596 696 43 70 11","address":"Boulevard Allègre, MARINA, 97290 Le Marin","payment":["Cartes bancaires","Espèces","Virement bancaire"],"website":"https://www.centraledubateau.fr/","facebook":"https://www.facebook.com/CentraleduBateau.fr","instagram":"https://instagram.com/centraledubateau","languages":["Français"],"priceRange":"230–320 €"},"opening_periods":[{"day":0,"opens":510,"closes":990},{"day":1,"opens":510,"closes":1050},{"day":2,"opens":510,"closes":1050},{"day":3,"opens":510,"closes":1050},{"day":4,"opens":510,"closes":1050},{"day":5,"opens":510,"closes":1050},{"day":6,"opens":510,"closes":990}],"hours_source":"https://www.martinique.org/fr/que-faire/sports-activites-nautiques/centrale-du-bateau","hours_updated_at":"2026-10-03T01:32:14.173086+00:00"},{"id":216,"name":"Cks Martinique / Cora Kite School","type":"activity","lat":14.5886392,"lng":-60.8495129,"location":"Le François","description":"A discreet kitesurf school at Cap Est offering personalised, made-to-measure kitesurf sessions in Martinique.","description_fr":"Une école de kitesurf discrète, à Cap Est, qui propose des séances de kitesurf sur mesure et personnalisées.","tags":["Kitesurf"],"sources":[{"url":"https://www.martinique.org/fr/que-faire/sports-activites-nautiques/cks-martinique-cora-kite-school","title":"Comité Martiniquais du Tourisme","fields":["Name","Town","Category","Description","Map point","Address","Telephone","Website","Price range","Payment","Languages spoken"],"checkedAt":"2026-10-02"}],"access":"unknown","published":true,"details":{"from":{"phone":{"url":"https://www.martinique.org/fr/que-faire/sports-activites-nautiques/cks-martinique-cora-kite-school","checkedAt":"2026-10-02"},"address":{"url":"https://www.martinique.org/fr/que-faire/sports-activites-nautiques/c