pour les pratiquants autonomes.","tags":["Kitesurf"],"sources":[{"url":"https://www.martinique.org/fr/que-faire/sports-activites-nautiques/club-nautique-du-vauclin","title":"Comité Martiniquais du Tourisme","fields":["Name","Town","Category","Description","Map point","Address","Telephone","Price range","Payment","Languages spoken"],"checkedAt":"2026-10-02"}],"access":"unknown","published":true,"details":{"from":{"phone":{"url":"https://www.martinique.org/fr/que-faire/sports-activites-nautiques/club-nautique-du-vauclin","checkedAt":"2026-10-02"},"address":{"url":"https://www.martinique.org/fr/que-faire/sports-activites-nautiques/club-nautique-du-vauclin","checkedAt":"2026-10-02"},"payment":{"url":"https://www.martinique.org/fr/que-faire/sports-activites-nautiques/club-nautique-du-vauclin","checkedAt":"2026-10-02"},"languages":{"url":"https://www.martinique.org/fr/que-faire/sports-activites-nautiques/club-nautique-du-vauclin","checkedAt":"2026-10-02"},"priceRange":{"url":"https://www.martinique.org/fr/que-faire/sports-activites-nautiques/club-nautique-du-vauclin","checkedAt":"2026-10-02"}},"phone":"+596 596 74 50 83","address":"Pointe Faula, 97280 Le Vauclin","payment":["Cartes bancaires","Chèques bancaires et postaux","Chèques vacances","Virement bancaire"],"languages":["Anglais","Français"],"priceRange":"25 €"}},{"id":219,"name":"Club Subaquatique De Case-Pilote","type":"activity","lat":14.6431,"lng":-61.137499,"location":"Case-Pilote","description":"A non-profit diving club and water-sports and leisure centre in Case-Pilote, for beginners and experts, run by qualified, experienced professionals who care about teaching and safety.","description_fr":"Un club associatif de plongée et centre de loisirs aquatiques à Case-Pilote, pour débutants comme experts, animé par des professionnels expérimentés attentifs à l’enseignement et à la sécurité.","tags":["Diving"],"sources":[{"url":"https://www.martinique.org/fr/que-faire/sports-activites-nautiques/club-subaquatique-de-ca