as.","tags":["Boat Trip"],"sources":[{"url":"https://www.martinique.org/fr/que-faire/sports-activites-nautiques/madacruise","title":"Comité Martiniquais du Tourisme","fields":["Name","Town","Category","Description","Map point","Address","Telephone","Social media","Payment","Languages spoken"],"checkedAt":"2026-10-02"}],"access":"unknown","published":true,"details":{"from":{"phone":{"url":"https://www.martinique.org/fr/que-faire/sports-activites-nautiques/madacruise","checkedAt":"2026-10-02"},"address":{"url":"https://www.martinique.org/fr/que-faire/sports-activites-nautiques/madacruise","checkedAt":"2026-10-02"},"payment":{"url":"https://www.martinique.org/fr/que-faire/sports-activites-nautiques/madacruise","checkedAt":"2026-10-02"},"instagram":{"url":"https://www.martinique.org/fr/que-faire/sports-activites-nautiques/madacruise","checkedAt":"2026-10-02"},"languages":{"url":"https://www.martinique.org/fr/que-faire/sports-activites-nautiques/madacruise","checkedAt":"2026-10-02"}},"phone":"+596 696 91 22 97","address":"Ponton bourg du Robert, BOULEVARD HENRI AUZE, 97231 Le Robert","payment":["Cartes bancaires","Chèques vacances","Espèces","Virement bancaire"],"instagram":"https://instagram.com/madacruise","languages":["Français"]}},{"id":266,"name":"Madiana Blue Plaisir","type":"activity","lat":14.47395387,"lng":-61.0080801,"location":"Le Diamant","description":"A family-scale dive centre at Le Diamant, founded by a diver returning to his native island to combine diving with Antillean culture, with a strong focus on safety and enjoyment.","description_fr":"Un centre de plongée à dimension familiale au Diamant, créé par un plongeur revenu sur son île natale pour allier plongée et culture antillaise, avec une exigence de sécurité et un souci du plaisir de chacun.","tags":["Diving"],"sources":[{"url":"https://www.martinique.org/fr/que-faire/sports-activites-nautiques/madiana-blue-plaisir","title":"Comité Martiniquais du Tourisme","fields":["Name","Town","Category","Descr