 à la journée pour une journée détente dans la mangrove ou à l’îlet Chancel, au Robert : plage, fonds blancs, iguanes, ruines d’une habitation sucrière et mangrove.","tags":["Kayak"],"sources":[{"url":"https://www.martinique.org/fr/que-faire/sports-activites-nautiques/madinina-kayaks","title":"Comité Martiniquais du Tourisme","fields":["Name","Town","Category","Description","Map point","Address","Telephone","Website","Social media","Payment","Languages spoken","Opening hours"],"checkedAt":"2026-10-02"}],"access":"unknown","published":true,"details":{"from":{"phone":{"url":"https://www.martinique.org/fr/que-faire/sports-activites-nautiques/madinina-kayaks","checkedAt":"2026-10-02"},"address":{"url":"https://www.martinique.org/fr/que-faire/sports-activites-nautiques/madinina-kayaks","checkedAt":"2026-10-02"},"payment":{"url":"https://www.martinique.org/fr/que-faire/sports-activites-nautiques/madinina-kayaks","checkedAt":"2026-10-02"},"website":{"url":"https://www.martinique.org/fr/que-faire/sports-activites-nautiques/madinina-kayaks","checkedAt":"2026-10-02"},"facebook":{"url":"https://www.martinique.org/fr/que-faire/sports-activites-nautiques/madinina-kayaks","checkedAt":"2026-10-02"},"languages":{"url":"https://www.martinique.org/fr/que-faire/sports-activites-nautiques/madinina-kayaks","checkedAt":"2026-10-02"}},"phone":"+596 696 39 80 27","address":"Pointe Savane, Chemin de l''îlet, 97231 Le Robert","payment":["Cartes bancaires","Chèques bancaires et postaux","Chèques vacances","Virement bancaire"],"website":"https://www.kayak-martinique.com/","facebook":"https://www.facebook.com/Madinina-Kayaks-631399983669864","languages":["Anglais","Français"]},"opening_periods":[{"day":0,"opens":540,"closes":780},{"day":0,"opens":780,"closes":1020},{"day":1,"opens":540,"closes":780},{"day":1,"opens":780,"closes":1020},{"day":2,"opens":540,"closes":780},{"day":2,"opens":780,"closes":1020},{"day":3,"opens":540,"closes":780},{"day":3,"opens":780,"closes":1020},{"day":4,"opens":540