ns sportives d’une demi-journée et la formation au permis côtier.","tags":["Boat Trip"],"sources":[{"url":"https://www.martinique.org/fr/que-faire/sports-activites-nautiques/nautitan","title":"Comité Martiniquais du Tourisme","fields":["Name","Town","Category","Description","Map point","Address","Telephone","Website","Social media","Payment","Languages spoken","Opening hours"],"checkedAt":"2026-10-02"}],"access":"unknown","published":true,"details":{"from":{"phone":{"url":"https://www.martinique.org/fr/que-faire/sports-activites-nautiques/nautitan","checkedAt":"2026-10-02"},"address":{"url":"https://www.martinique.org/fr/que-faire/sports-activites-nautiques/nautitan","checkedAt":"2026-10-02"},"payment":{"url":"https://www.martinique.org/fr/que-faire/sports-activites-nautiques/nautitan","checkedAt":"2026-10-02"},"website":{"url":"https://www.martinique.org/fr/que-faire/sports-activites-nautiques/nautitan","checkedAt":"2026-10-02"},"facebook":{"url":"https://www.martinique.org/fr/que-faire/sports-activites-nautiques/nautitan","checkedAt":"2026-10-02"},"instagram":{"url":"https://www.martinique.org/fr/que-faire/sports-activites-nautiques/nautitan","checkedAt":"2026-10-02"},"languages":{"url":"https://www.martinique.org/fr/que-faire/sports-activites-nautiques/nautitan","checkedAt":"2026-10-02"}},"phone":"+596 696 31 81 38","address":"Chez M.Laroche, 8 Lot Batterie, Rue de la Batterie, 97217 Les Anses-D''Arlet","payment":["Chèques bancaires et postaux","Virement bancaire"],"website":"https://www.nautitan.com/","facebook":"https://www.facebook.com/nautitan.sarl","instagram":"https://instagram.com/nautitan.sarl","languages":["Anglais","Espagnol","Français"]},"opening_periods":[{"day":0,"opens":480,"closes":720},{"day":0,"opens":720,"closes":1200},{"day":1,"opens":480,"closes":720},{"day":1,"opens":720,"closes":1200},{"day":2,"opens":480,"closes":720},{"day":2,"opens":720,"closes":1200},{"day":3,"opens":480,"closes":720},{"day":3,"opens":720,"closes":1200},{"day":4,"opens":